insert into public.pages
  (id, legacy_ref, slug, parent_id, path, sort_order, title, template, blueprint, published, show_in_nav, description, short_description, intro, welcome_line, main_image_asset_id, program_image_asset_id, important_notes, legacy, source_updated_at, source_updated_by)
values
  (public.ces_uuid('pages', 'home'), 'home', 'home', null, '/', 1, 'Home', 'home', 'home', true, true, null, null, 'We are a small, non-profit preschool located in the heart of Cambridge. Our mission is to provide a joyful, warm, and stimulating first school experience for our community''s youngest learners. Our philosophy is built upon a foundation of equity, inclusion, and above all community.', 'Welcome to Cambridge-Ellis School!', null, null, null, '{"hero":["xcooking.jpg","Xcoolkids.jpg","XGerlinde1.jpg","1WE-PLAY.jpg","2WE-EXPLORE.jpg","hands.jpg"]}'::jsonb, '2026-07-22T14:23:49.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', '523d62db-c1ac-4068-af18-6950b8a80ff7'), '523d62db-c1ac-4068-af18-6950b8a80ff7', 'about', null, '/about', 2, 'About', 'flexpage', 'flexible_content_page', true, true, null, null, null, null, public.ces_uuid('assets', 'About.jpg'), null, null, '{"include":true}'::jsonb, '2024-02-29T23:53:21.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', 'd45b3a16-f89d-4ed5-b078-81bbe6b0c5aa'), 'd45b3a16-f89d-4ed5-b078-81bbe6b0c5aa', 'a-letter-from-the-director', public.ces_uuid('pages', '523d62db-c1ac-4068-af18-6950b8a80ff7'), '/about/a-letter-from-the-director', 1, 'A Letter from the Director', 'flexpage', 'flexible_content_page', true, true, null, null, null, null, public.ces_uuid('assets', 'pxl_20230411_134447805.mp.jpg'), null, null, '{}'::jsonb, '2024-02-13T16:34:19.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', 'fe10778f-dff3-47af-bf1b-b1972057450f'), 'fe10778f-dff3-47af-bf1b-b1972057450f', 'mission-and-philosophy', public.ces_uuid('pages', '523d62db-c1ac-4068-af18-6950b8a80ff7'), '/about/mission-and-philosophy', 2, 'Mission and Philosophy', 'flexpage', 'flexible_content_page', true, true, null, null, null, null, public.ces_uuid('assets', '20201001_102723-1635523304.jpg'), null, null, '{}'::jsonb, '2021-10-29T16:01:50.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', 'a0f1b991-763a-4fbd-a494-914d601d634e'), 'a0f1b991-763a-4fbd-a494-914d601d634e', 'careers', public.ces_uuid('pages', '523d62db-c1ac-4068-af18-6950b8a80ff7'), '/about/careers', 3, 'Careers', 'flexpage', 'flexible_content_page', true, true, null, null, null, null, public.ces_uuid('assets', 'IMG_5104-1635179815.jpg'), null, null, '{}'::jsonb, '2026-06-03T13:04:49.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', 'af114a97-d3b3-4535-a2b9-f9b31735b609'), 'af114a97-d3b3-4535-a2b9-f9b31735b609', 'history', public.ces_uuid('pages', '523d62db-c1ac-4068-af18-6950b8a80ff7'), '/about/history', 4, 'History', 'flexpage', 'flexible_content_page', true, true, null, null, null, null, public.ces_uuid('assets', 'IMG_3250.jpg'), null, null, '{}'::jsonb, '2024-02-13T16:26:42.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', '58a3827b-888a-4051-815b-563fd036e1ee'), '58a3827b-888a-4051-815b-563fd036e1ee', 'events', null, '/events', 3, 'Events', 'events', 'landing_page', true, true, '[no need to put anything here; use the Events collection to add events]', null, null, null, null, null, null, '{"include":true}'::jsonb, '2023-08-02T22:03:35.000Z', 'conrad.fulbrook@gmail.com'),
  (public.ces_uuid('pages', '7039e0d2-553e-4204-9541-d39edf1ff500'), '7039e0d2-553e-4204-9541-d39edf1ff500', 'programs', null, '/programs', 4, 'Programs', 'programs', 'landing_page', true, true, 'Cambridge Ellis is proud to offer an exciting range of year-round programs for children aged toddler through upper preschool. Explore each of our offerings below, and enroll now!', null, null, null, null, null, null, '{"include":true}'::jsonb, '2024-02-13T16:10:40.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', '8621d55b-cbfc-4cd1-b7c6-97a5a38e471b'), '8621d55b-cbfc-4cd1-b7c6-97a5a38e471b', 'day-programs', public.ces_uuid('pages', '7039e0d2-553e-4204-9541-d39edf1ff500'), '/programs/day-programs', 1, 'Day Programs', 'programsumbrella', 'programsumbrella', true, true, 'The Cambridge-Ellis Day Program runs Monday through Friday, from 8:30 a.m. until 3:00 p.m. (with an option for daily dismissal at noon). We serve toddlers and preschool age children in seven classrooms that are grouped according to development. The curriculum at Cambridge-Ellis School is designed to promote social and emotional, cognitive, and pre-literacy skills and to provide a foundation for the study of mathematics and science. We have great respect for children as thinkers and learners and value their contributions to joint investigations. We believe that children learn best through play, active participation and engagement with teachers, peers, and materials.', 'Play-based, emergent learning is at the heart of our Day Program. We serve toddlers and preschool age children in seven classrooms that are grouped according to age and development.', null, null, null, public.ces_uuid('assets', '20210913_112628-1635953342.jpg'), null, '{"parent":"261c91f6-648b-409b-8457-02a740156d6a"}'::jsonb, '2021-11-05T14:32:59.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', 'a4fe025d-3d9c-4131-8481-ec2718833b30'), 'a4fe025d-3d9c-4131-8481-ec2718833b30', 'language-programs', public.ces_uuid('pages', '7039e0d2-553e-4204-9541-d39edf1ff500'), '/programs/language-programs', 2, 'Afternoon Language Program', 'programsumbrella', 'programsumbrella', true, true, 'Our Language Program runs daily from 3:00-6:00pm. We offer children a language immersion experience in French, Spanish, or Mandarin, as well as English in the Rainbow Room. Teachers in each of the four classrooms infuse art, music, outdoor exploration, print, and materials from other cultures into the daily experience of each child. The program includes language instruction as an organic part of a relaxed, nurturing learning environment supported with developmentally-appropriate arts, crafts, music, cooking, and outdoor play.', 'Our afternoon Language Program offers a unique, immersive experience in French, Mandarin, or Spanish for children ages 2.9 through 6 years old, whether they are fluent or just starting to explore the target language. Children in 1st through 4th grade may join our Mandarin Jade classroom. Toddler programming, primarily in English, is also available for children ages 1.9 to 2.9.', null, null, null, public.ces_uuid('assets', '20210924_161120.jpg'), null, '{"parent":"261c91f6-648b-409b-8457-02a740156d6a"}'::jsonb, '2026-01-29T01:29:40.000Z', 'conrad.fulbrook@gmail.com'),
  (public.ces_uuid('pages', '9eb88d65-ada5-400c-b868-56bd69ee0744'), '9eb88d65-ada5-400c-b868-56bd69ee0744', 'school-age-mandarin-for-grades-k-through-3rd', public.ces_uuid('pages', '7039e0d2-553e-4204-9541-d39edf1ff500'), '/programs/school-age-mandarin-for-grades-k-through-3rd', 3, 'School Age Mandarin - Grades K through 3', 'programsumbrella', 'programsumbrella', false, false, null, null, null, null, null, null, null, '{"parent":"7039e0d2-553e-4204-9541-d39edf1ff500"}'::jsonb, '2026-01-07T14:05:04.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3'), '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3', 'enrichment-programs', public.ces_uuid('pages', '7039e0d2-553e-4204-9541-d39edf1ff500'), '/programs/enrichment-programs', 4, 'Enrichment Programs', 'programsumbrellasummer', 'programsumbrellasummer', true, true, 'A focus on the arts and nature is an integral part of the Cambridge-Ellis philosophy. Though our classroom teachers integrate these experiences into their daily practice, we supplement this learning with the following Enrichment Programs: Arts Adventure, Nature Days, and our unique Artisan Program.', 'We supplement our Day and Language Programs with a variety of Enrichment programming focused on the arts, music, and outdoor learning.', null, null, null, public.ces_uuid('assets', '20210920_162107-1635515402.jpg'), null, '{"parent":"261c91f6-648b-409b-8457-02a740156d6a"}'::jsonb, '2025-09-10T13:19:42.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', '21904ad8-20a4-4672-a6eb-51204901e0e7'), '21904ad8-20a4-4672-a6eb-51204901e0e7', 'summer-programs', public.ces_uuid('pages', '7039e0d2-553e-4204-9541-d39edf1ff500'), '/programs/summer-programs', 5, 'Summer Programs', 'programsumbrellasummer', 'programsumbrellasummer', true, true, E'June and July are full of fun, exploration, and water play at our CES summer program! We offer 8:30-12:00pm, 8:30-4:00pm, and 8:30 to 5:00pm programming for Toddlers and Preschoolers alike. \n\nToddler-age classrooms are available for children 1.9-2.8. English preschool classes are for ages 2.9-5.11, and Language Immersion classrooms in French, Mandarin, and Spanish are available for children ages 3 to 6.11.\n\nEmail Katie@Cambridge-Ellis.org for more information.', E'In June and July, our English and Language Immersion programs drive our enriching and joyful summer program. Our playgrounds are transformed into outdoor classrooms with water play, art experiences, building materials, books and mud kitchens.\n\nOur hours are 8:30 to noon, 8:30 to 4:00pm, or 8:30 to 5. Toddler-age classrooms are available for children 1.9-2.8. English preschool classes are for ages 2.9-5.11, and Language Immersion classrooms in French, Mandarin, and Spanish are available for children over the age of 3 years and up through age 6.11. Email Katie@Cambridge-Ellis.org for more information.', null, null, public.ces_uuid('assets', 'IMG_9044.jpg'), public.ces_uuid('assets', 'IMG_1507.jpg'), '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Important Notes Regarding Registration:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://cambridgeellis.campbrainregistration.com","rel":null,"target":"_blank","title":"CampBrain 2026 Registration"}},{"type":"bold"}],"text":"Registration"},{"type":"text","text":" opens to the public on Sunday, February 22nd at 9pm."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Children must be 3 years old at the start of the program in order to enroll in any of the Language Immersion programs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A deposit is required to complete your registration. Your deposit amount is shown in the \u201cPayment Plan(s)\u201d section at checkout. The remainder of the balance must be paid by April 15. If you need to withdraw or cancel completely, you may inform us by April 1st to be refunded."}]}]}]}]}'::jsonb, '{"parent":"261c91f6-648b-409b-8457-02a740156d6a"}'::jsonb, '2026-02-23T01:53:00.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', 'b6be47de-19f3-467c-9983-5629d08418ef'), 'b6be47de-19f3-467c-9983-5629d08418ef', 'community', null, '/community', 5, 'Community', 'flexpage', 'flexible_content_page', true, true, null, null, null, null, public.ces_uuid('assets', 'IMG_4454.jpg'), null, null, '{"include":true}'::jsonb, '2022-01-04T18:54:03.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', '69ccd1a0-7018-443a-aadc-3dd3dfe1bc06'), '69ccd1a0-7018-443a-aadc-3dd3dfe1bc06', 'board-of-directors', public.ces_uuid('pages', 'b6be47de-19f3-467c-9983-5629d08418ef'), '/community/board-of-directors', 1, 'Board of Directors', 'peopleindex', 'landing_page', true, true, 'The CES Board of Directors is responsible for overseeing the affairs of the Cambridge-Ellis School. The board’s responsibilities include: defining and aligning resources with the school’s mission, vision and strategic goals; ensuring CES’s financial sustainability through strategic financial planning and oversight and approval of CES’s budgets and fundraising activities; selecting, supporting, and evaluating the school director.', null, null, null, null, null, null, '{"parent":"b6be47de-19f3-467c-9983-5629d08418ef"}'::jsonb, '2021-10-29T12:55:58.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', '0d5bb459-de3b-466b-827f-89b37430222d'), '0d5bb459-de3b-466b-827f-89b37430222d', 'leadership-team', public.ces_uuid('pages', 'b6be47de-19f3-467c-9983-5629d08418ef'), '/community/leadership-team', 2, 'Leadership Team', 'peopleindex', 'landing_page', true, true, 'The Cambridge-Ellis Leadership Team is composed of experts in the field of early childhood education, development, finance, and administration. Their purpose is to facilitate the work of CES''s incredible teachers and guide families through a joyful first school experience.', null, null, null, null, null, null, '{"parent":"b6be47de-19f3-467c-9983-5629d08418ef"}'::jsonb, '2021-10-29T17:16:56.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', 'ca8bb0dd-e555-4cd3-81e7-4e545259047c'), 'ca8bb0dd-e555-4cd3-81e7-4e545259047c', 'teaching-team', public.ces_uuid('pages', 'b6be47de-19f3-467c-9983-5629d08418ef'), '/community/teaching-team', 3, 'Teaching Team', 'peopleindex', 'landing_page', true, true, 'At Cambridge-Ellis, we pride ourselves on cultivating incredibly skilled and passionate teachers with a diverse range of backgrounds, educations, and perspectives. Our teachers take advantage of regular staff development and education opportunities, and we enjoy an outstanding legacy of staff longevity. Many of our teachers have been at CES for over 20 years!', null, null, null, null, null, null, '{"parent":"b6be47de-19f3-467c-9983-5629d08418ef"}'::jsonb, '2021-10-29T13:11:17.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('pages', '68ab3ced-2c3f-4d30-8c42-1eeb2f3f2300'), '68ab3ced-2c3f-4d30-8c42-1eeb2f3f2300', 'families', public.ces_uuid('pages', 'b6be47de-19f3-467c-9983-5629d08418ef'), '/community/families', 4, 'Families', 'flexpage', 'flexible_content_page', true, true, null, null, null, null, public.ces_uuid('assets', 'IMG_1716-1635524643.JPG'), null, null, '{}'::jsonb, '2021-11-28T01:53:54.000Z', 'conrad.fulbrook@gmail.com'),
