  (public.ces_uuid('page_sections', 'a4fe025d-3d9c-4131-8481-ec2718833b30:slideshow:0'), 'a4fe025d-3d9c-4131-8481-ec2718833b30:slideshow:0', public.ces_uuid('pages', 'a4fe025d-3d9c-4131-8481-ec2718833b30'), null, 'image', 1, true, null, public.ces_uuid('assets', 'IMG_0728.JPG'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', 'a4fe025d-3d9c-4131-8481-ec2718833b30:slideshow:1'), 'a4fe025d-3d9c-4131-8481-ec2718833b30:slideshow:1', public.ces_uuid('pages', 'a4fe025d-3d9c-4131-8481-ec2718833b30'), null, 'image', 2, true, null, public.ces_uuid('assets', 'IMG_0528.JPG'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', 'a4fe025d-3d9c-4131-8481-ec2718833b30:slideshow:2'), 'a4fe025d-3d9c-4131-8481-ec2718833b30:slideshow:2', public.ces_uuid('pages', 'a4fe025d-3d9c-4131-8481-ec2718833b30'), null, 'image', 3, true, null, public.ces_uuid('assets', 'IMG_2919.jpg'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', 'a4fe025d-3d9c-4131-8481-ec2718833b30:slideshow:3'), 'a4fe025d-3d9c-4131-8481-ec2718833b30:slideshow:3', public.ces_uuid('pages', 'a4fe025d-3d9c-4131-8481-ec2718833b30'), null, 'image', 4, true, null, public.ces_uuid('assets', 'IMG_1021.JPG'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '9eb88d65-ada5-400c-b868-56bd69ee0744:add_content:0'), '9eb88d65-ada5-400c-b868-56bd69ee0744:add_content:0', public.ces_uuid('pages', '9eb88d65-ada5-400c-b868-56bd69ee0744'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Our school-age Mandarin programming, grades K through 3, expands upon the current CES philosophy. This program will follow a project-based model where children work collaboratively in the target language on large-scale projects that interest them, bringing in cultural and local community components and connections, as well as providing opportunities for DEI learning and activism. Mini lessons will target specific language learning, and support beginning literacy skills. Children will have regular opportunities for outdoor play, art, cooking, music, and movement."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"mjvnt9gf"}'::jsonb),
  (public.ces_uuid('page_sections', '9eb88d65-ada5-400c-b868-56bd69ee0744:add_content:1'), '9eb88d65-ada5-400c-b868-56bd69ee0744:add_content:1', public.ces_uuid('pages', '9eb88d65-ada5-400c-b868-56bd69ee0744'), null, 'image', 2, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"mjvnwyg6"}'::jsonb),
  (public.ces_uuid('page_sections', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:slideshow:0'), '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:slideshow:0', public.ces_uuid('pages', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3'), null, 'image', 1, true, null, public.ces_uuid('assets', 'IMG_4061.jpg'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:slideshow:1'), '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:slideshow:1', public.ces_uuid('pages', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3'), null, 'image', 2, true, null, public.ces_uuid('assets', '20210927_163507.jpg'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:slideshow:2'), '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:slideshow:2', public.ces_uuid('pages', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3'), null, 'image', 3, true, null, public.ces_uuid('assets', 'IMG_4064.JPG'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:slideshow:3'), '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:slideshow:3', public.ces_uuid('pages', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3'), null, 'image', 4, true, null, public.ces_uuid('assets', '69617404_523065031569707_108148148602370874_n.jpg'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:programs_offered:0'), '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:programs_offered:0', public.ces_uuid('pages', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3'), null, 'program', 5, true, null, null, null, null, null, null, null, null, null, 'Arts Adventure', 'Arts Adventure connects children to their world through artistic expression. Students participate in music, visual arts, dance and movement, drama, and literature, weekly for 30 - 45 minutes. Arts Adventure is designed to extend upon both classroom and Artisan Program themes, as well as provide Language Program students experiences in their cultural arts.', null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"bQARazRc"}'::jsonb),
  (public.ces_uuid('page_sections', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:programs_offered:1'), '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:programs_offered:1', public.ces_uuid('pages', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3'), null, 'program', 6, false, null, null, null, null, null, null, null, null, null, 'Music with Anna', 'Each month, children develop their musical roots and celebrate the international language of music with our specialist, Anna Laufenberg. Through songs and creative movement Anna introduces students to beats, rhythms, and scales. She delights and inspires children with her array of musical instruments from flute to contrabass.', null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"hFuj951j"}'::jsonb),
  (public.ces_uuid('page_sections', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:programs_offered:2'), '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:programs_offered:2', public.ces_uuid('pages', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3'), null, 'program', 7, true, null, null, null, null, null, null, null, null, null, 'Nature Program', 'A hidden gem in the heart of Cambridge, our playgrounds inspire endless opportunities for adventure. Digging moats, climbing trees, transporting logs, cooking in mud kitchens, and observing chickens are part of our daily outdoor experiences. Weekly neighborhood walks to community green spaces and regularly scheduled visits from Habitat Wildlife Sanctuary further inspire awe and wonder as children learn about their world through discovery.', null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"i9sHm5z1"}'::jsonb),
  (public.ces_uuid('page_sections', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:programs_offered:3'), '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3:programs_offered:3', public.ces_uuid('pages', '06a2913a-6fe2-4d75-ae0c-77f0ecb6b5b3'), null, 'program', 8, true, null, null, null, null, null, null, null, null, null, 'Artisan Program', 'The Ann Murphy Artisan Program celebrates the artistic process, from imagination to creation. An endowment from the late Ann Murphy, beloved CES teacher and administrator, supports artist residencies for the children, professional development for our teachers and theme inspired family events.', null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"s9sFlWXi"}'::jsonb),
  (public.ces_uuid('page_sections', '21904ad8-20a4-4672-a6eb-51204901e0e7:slideshow:0'), '21904ad8-20a4-4672-a6eb-51204901e0e7:slideshow:0', public.ces_uuid('pages', '21904ad8-20a4-4672-a6eb-51204901e0e7'), null, 'image', 1, true, null, public.ces_uuid('assets', 'summer.jpg'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '21904ad8-20a4-4672-a6eb-51204901e0e7:slideshow:1'), '21904ad8-20a4-4672-a6eb-51204901e0e7:slideshow:1', public.ces_uuid('pages', '21904ad8-20a4-4672-a6eb-51204901e0e7'), null, 'image', 2, true, null, public.ces_uuid('assets', 'IMG_3422.jpg'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '21904ad8-20a4-4672-a6eb-51204901e0e7:slideshow:2'), '21904ad8-20a4-4672-a6eb-51204901e0e7:slideshow:2', public.ces_uuid('pages', '21904ad8-20a4-4672-a6eb-51204901e0e7'), null, 'image', 3, true, null, public.ces_uuid('assets', 'IMG_0051-1635514734.jpg'), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '21904ad8-20a4-4672-a6eb-51204901e0e7:programs_offered:0'), '21904ad8-20a4-4672-a6eb-51204901e0e7:programs_offered:0', public.ces_uuid('pages', '21904ad8-20a4-4672-a6eb-51204901e0e7'), null, 'program', 4, true, null, null, null, null, null, null, null, null, null, 'Toddler Classes or Preschool Classes in English, French, Mandarin, or Spanish', null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"ml1ape2m"}'::jsonb),
  (public.ces_uuid('page_sections', '21904ad8-20a4-4672-a6eb-51204901e0e7:sessions:0'), '21904ad8-20a4-4672-a6eb-51204901e0e7:sessions:0', public.ces_uuid('pages', '21904ad8-20a4-4672-a6eb-51204901e0e7'), null, 'session', 5, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Summer 2026', 'June 22nd – July 17th (We are closed Friday July 3rd)', null, null, '{}'::jsonb, '{"set_id":"v9xeLPP5"}'::jsonb),
  (public.ces_uuid('page_sections', 'b6be47de-19f3-467c-9983-5629d08418ef:add_content:0'), 'b6be47de-19f3-467c-9983-5629d08418ef:add_content:0', public.ces_uuid('pages', 'b6be47de-19f3-467c-9983-5629d08418ef'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Words from Community Members"}]},{"type":"paragraph","content":[{"type":"text","text":"Community is what drives the mission of Cambridge-Ellis School. We are constantly working towards the ideals of inclusion, equity, and a true sense of belonging for all of our community members. Testimonials from a variety of community members provide a window into the community we are nurturing at CES."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', 'b6be47de-19f3-467c-9983-5629d08418ef:add_content:1'), 'b6be47de-19f3-467c-9983-5629d08418ef:add_content:1', public.ces_uuid('pages', 'b6be47de-19f3-467c-9983-5629d08418ef'), null, 'quote', 2, true, null, null, null, null, 'As a multiracial, multicultural, middle-class family, we wanted our child’s first school experience to be in a loving, nurturing, and welcoming place, and in a community that valued all forms of diversity. We found in Cambridge-Ellis a second home, where our child was truly known and loved, and where we felt deeply connected.', 'CES Caregiver', null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', 'b6be47de-19f3-467c-9983-5629d08418ef:add_content:2'), 'b6be47de-19f3-467c-9983-5629d08418ef:add_content:2', public.ces_uuid('pages', 'b6be47de-19f3-467c-9983-5629d08418ef'), null, 'quote', 3, true, null, null, null, null, 'CES values it''s families, children, and developmental learning. As a teacher I feel that I have the respect, the professional understanding, the resources, and the support to do my job. It is also a safe space to explore new curriculum and methods of teaching to best serve the current population of children. I appreciate that I can tailor my teaching methods to the specific group that I have each year.', 'CES Teacher', null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', 'b6be47de-19f3-467c-9983-5629d08418ef:add_content:3'), 'b6be47de-19f3-467c-9983-5629d08418ef:add_content:3', public.ces_uuid('pages', 'b6be47de-19f3-467c-9983-5629d08418ef'), null, 'quote', 4, true, null, null, null, null, 'We feel sincerely grateful to have crossed paths with the educators and administrators at CES. This contact has taught us to be better parents and has given our child a strong foundation which we couldn''t have done on our own. We are full of gratitude.', 'CES Caregiver', null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '68ab3ced-2c3f-4d30-8c42-1eeb2f3f2300:add_content:0'), '68ab3ced-2c3f-4d30-8c42-1eeb2f3f2300:add_content:0', public.ces_uuid('pages', '68ab3ced-2c3f-4d30-8c42-1eeb2f3f2300'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Parent involvement is one of the hallmarks of Cambridge-Ellis. We believe that forming collaborative partnerships with parents is crucial to building trusting relationships and improves outcomes for young children. Parents and teachers work together to nurture children and optimize each child\u2019s experience. We communicate and partner with parents through a variety of forums and believe that the home/school connection is a critical element of a child\u2019s early education."}]},{"type":"paragraph","content":[{"type":"text","text":"Visit our "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/giving/ways-to-give","rel":null,"target":null,"title":null}}],"text":"Ways to Give"},{"type":"text","text":" page for ideas on how to get involved!"}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '9d1c2779-c059-4c7d-9bdc-2a26cef3877e:add_content:0'), '9d1c2779-c059-4c7d-9bdc-2a26cef3877e:add_content:0', public.ces_uuid('pages', '9d1c2779-c059-4c7d-9bdc-2a26cef3877e'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Taiwan Exchange Program"}]},{"type":"paragraph","content":[{"type":"text","text":"The Cambridge-Ellis School takes part in a unique international cultural exchange program with a school in Taiwan, St. James Preschool."}]},{"type":"paragraph","content":[{"type":"text","text":"Each year, we host one teacher from St. James Preschool, who teaches in our Mandarin Program at CES. We send two of our own teachers to Taiwan each summer to teach in the St. James summer English program."}]},{"type":"paragraph","content":[{"type":"text","text":"This cultural exchange is highly valuable and enriching to both our teaching communities and fosters understanding and cross-cultural relationships."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Artist in Residence Program"}]},{"type":"paragraph","content":[{"type":"text","text":"Through the Ann Murphy Artisan Program, we host artists in residence every year. Recent themes included dance, textile, and healthy cooking. For each of the themes we invite artists, musicians, specialists such as bee keepers, chefs, dancers or story tellers to work directly with our children and introduce their art."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Student Teaching"}]},{"type":"paragraph","content":[{"type":"text","text":"Cambridge-Ellis is a teaching school in the truest sense and we mentor a number of student teachers every year from universities including Wheelock College, Lesley University,\u00a0Tufts University,\u00a0and the University of Massachusetts."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Internships"}]},{"type":"paragraph","content":[{"type":"text","text":"In 2013 we formed a partnership with the Early Childhood Program at the Cambridge, Rindge and Latin School. We visit their classroom for activities and host their student teachers for observations and internships at CES."}]},{"type":"paragraph","content":[{"type":"text","text":"In 2014, we began hosting student interns from the Cambridge Community Charter School. Student Interns from CCCS are seniors in High School and complete 100 hours during their internship. Completing an internship in a community organization is a requirement for graduation."}]},{"type":"paragraph","content":[{"type":"text","text":"In 2015 we began to welcome students from the Boston Arts Academy to volunteer during their community day. Students performed for CES children and offered an instrument petting zoo."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', 'c122c5f5-7df6-4f26-8080-0888c282b224:add_content:0'), 'c122c5f5-7df6-4f26-8080-0888c282b224:add_content:0', public.ces_uuid('pages', 'c122c5f5-7df6-4f26-8080-0888c282b224'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Enrollment Ages"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Toddler Room (ages 1 year 9 months - 2 years 8 months by September)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lower Preschool (ages 2 years 9 months by September)*"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Upper Preschool (ages 3 years 7 months - 5 years by September)*"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After School Toddler Program (ages 1 year 9 months - 2 years 8 months by September)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After School Language Programs (ages 2 years 9 months - 6 years by September)*"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After School Mandarin Immersion Program for Kindergarten - 4th Grade"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"*age range will vary year to year depending on enrollment"}]},{"type":"paragraph","content":[{"type":"text","text":"CES works collaboratively with a number of different agencies, public and private, as well as renowned experts in areas of child development, including a child development specialist, speech and language pathologist, and child psychologist. Our teaching faculty receives ongoing training and consultation by experts in the field. We welcome specialists and therapists into our classrooms to provide special support services to children during school hours.\u00a0"}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"CfW4Imz5"}'::jsonb),
  (public.ces_uuid('page_sections', '66afe361-c739-4275-ad7d-b48d1cde227d:add_content:0'), '66afe361-c739-4275-ad7d-b48d1cde227d:add_content:0', public.ces_uuid('pages', '66afe361-c739-4275-ad7d-b48d1cde227d'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Welcome to our community! In-person tours are available from October 1 to January 31, annually. During your tour with the Admissions Director, you will be able to learn more about the school, observe classrooms and teacher/child interactions, and meet with the Director of our school. We ask that all families submit an application before their tour date."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"To arrange a tour, please contact "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/community/christina-isidoro","rel":null,"target":null,"title":null}},{"type":"italic"}],"text":"Christina Isidoro, our Admissions Director"},{"type":"text","marks":[{"type":"italic"}],"text":" at "},{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:christina@cambridge-ellis.org","rel":null,"target":null,"title":null}},{"type":"italic"}],"text":"Christina@Cambridge-Ellis.org"}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"yKdnHzoX"}'::jsonb),
  (public.ces_uuid('page_sections', 'a1104c2b-9a1c-4e71-a25b-cdab3a77e936:add_content:0'), 'a1104c2b-9a1c-4e71-a25b-cdab3a77e936:add_content:0', public.ces_uuid('pages', 'a1104c2b-9a1c-4e71-a25b-cdab3a77e936'), null, 'text', 1, false, '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Language Program Spots still Available!"}]},{"type":"paragraph","content":[{"type":"text","text":"Spots are still available in our After School Language Immersion Program for the 2025-26 School Year. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://cambridge-ellis.myschoolapp.com/app/bbid/apply","rel":null,"target":null,"title":null}}],"text":"Please click here to submit your application!"}]},{"type":"paragraph","content":[{"type":"text","text":"Details about the application process, scheduling a school visit, and timeline will be emailed to you directly after submission of your application."}]},{"type":"paragraph","content":[{"type":"text","text":"Contact the Director of Admissions, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:christina@cambridge-ellis.org","rel":null,"target":null,"title":null}}],"text":"Christina Isidoro"},{"type":"text","text":", with any questions."}]},{"type":"paragraph"}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"cfKLTtNH"}'::jsonb),
  (public.ces_uuid('page_sections', 'a1104c2b-9a1c-4e71-a25b-cdab3a77e936:add_content:1'), 'a1104c2b-9a1c-4e71-a25b-cdab3a77e936:add_content:1', public.ces_uuid('pages', 'a1104c2b-9a1c-4e71-a25b-cdab3a77e936'), null, 'text', 2, false, '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"First Round Application Process"}]},{"type":"paragraph","content":[{"type":"text","text":"First, fill out an "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://cambridge-ellis.myschoolapp.com/app/embed#inquiry/40349","rel":null,"target":null,"title":null}}],"text":"Inquiry Form"},{"type":"text","text":". Our admissions director will then reach out to you to set up a tour and meeting (adults only) with our Director and/or Assistant Director."}]},{"type":"paragraph","content":[{"type":"text","text":"Then, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://cambridge-ellis.myschoolapp.com/app/bbid/apply","rel":null,"target":null,"title":null}}],"text":"create an online account on our application platform"},{"type":"text","text":" and submit the $55 application fee. We ask families to submit their applications before the day of their tour."}]},{"type":"paragraph","content":[{"type":"text","text":"Families will be notified of our decisions in mid March. A signed contract, accompanied by an enrollment deposit, ensures a child\u2019s placement for the fall. When the number of applicants exceeds the number of spaces, waitlist notifications will be sent, and families will be called from the waitlist as spots become available. Current and alumni families as well as children of staff are given enrollment priority."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"SmHOyMeB"}'::jsonb),
  (public.ces_uuid('page_sections', 'a1104c2b-9a1c-4e71-a25b-cdab3a77e936:add_content:2'), 'a1104c2b-9a1c-4e71-a25b-cdab3a77e936:add_content:2', public.ces_uuid('pages', 'a1104c2b-9a1c-4e71-a25b-cdab3a77e936'), null, 'text', 3, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The admissions season for the 2026-27 school year has officially closed, but we are still accepting applications to be considered for our waitlist. We do anticipate spots opening up in our after school Language Program, so please reach out to our Language Program Director, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:elisabeth@cambridge-ellis.org","rel":null,"target":null,"title":null}}],"text":"Elisabeth Guenette"},{"type":"text","text":", if you want to learn more about that unique program."}]},{"type":"paragraph","content":[{"type":"text","text":"Contact our Admissions Director, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:christina@cambridge-ellis.org","rel":null,"target":null,"title":null}}],"text":"Christina Isidoro"},{"type":"text","text":", for all other inquiries."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"How to Apply"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Our admissions season begins on October 1st and runs through January. Please make sure you have completed the following steps before the January 31st deadline:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://cambridge-ellis.myschoolapp.com/app/embed?svcid=edu#inquiry/40349","rel":null,"target":"_blank","title":null}},{"type":"italic"}],"text":"Submit an Inquiry"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Schedule your Day or Language Program tour "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://calendly.com/ces-admissions/parent-tour","rel":null,"target":"_blank","title":null}},{"type":"italic"}],"text":"with Christina"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://cambridge-ellis.myschoolapp.com/app/bbid/apply","rel":null,"target":"_blank","title":null}},{"type":"italic"}],"text":"Submit an application"},{"type":"text","marks":[{"type":"italic"}],"text":" before your tour date"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Apply for Financial Aid if needed before the first Monday in February"}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"All late applicants will be added to our waitlist and be considered if later decision rounds are necessary.\u00a0"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Financial Aid"}]},{"type":"paragraph","content":[{"type":"text","text":"For more information about Cambridge-Ellis'' commitment to providing financial aid and the application process, visit our "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/admissions/financial-aid","rel":null,"target":null,"title":null}}],"text":"Financial Aid page"},{"type":"text","text":"."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"mnownw1o,339ZGsgN,iENR7N03"}'::jsonb),
  (public.ces_uuid('page_sections', '172c7bc4-6a88-4e1c-bc3c-1ce9ceb0ec84:add_content:0'), '172c7bc4-6a88-4e1c-bc3c-1ce9ceb0ec84:add_content:0', public.ces_uuid('pages', '172c7bc4-6a88-4e1c-bc3c-1ce9ceb0ec84'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"October 1 | "},{"type":"text","text":"online application available on Cambridge-Ellis website"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"First Saturday in November | "},{"type":"text","text":"Open House for perspective families"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"December 14 | "},{"type":"text","text":"re-enrollment forms and current & alumni siblings applications due"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"January 31 | "},{"type":"text","text":"new family applications due"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"First Monday in February | "},{"type":"text","text":"financial aid applications and documents due"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"February 15 | "},{"type":"text","text":"re-enrollment and current sibling contracts go out"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"March 10 | "},{"type":"text","text":"new family and alumni sibling contracts go out"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"April 30 | "},{"type":"text","text":"Visiting Day for children and families newly admitted to Cambridge-Ellis"}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"V0AodRHy,JwOWhzMf,SKb4ZMkY,AlHddgtK,T0a6tFjl,K7wdhBK3,6QoKTn8f,GSIp3ZeE"}'::jsonb),
  (public.ces_uuid('page_sections', '45a19839-c187-4be0-bedc-67f9f39aa5c5:add_content:0'), '45a19839-c187-4be0-bedc-67f9f39aa5c5:add_content:0', public.ces_uuid('pages', '45a19839-c187-4be0-bedc-67f9f39aa5c5'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"2026-27 Day Program"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":[330]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Toddler                                                     "}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"                                             "}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[330]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Morning (Mon-Fri, 8:30-12pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$31,360"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[330]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Full Day (Mon-Fri, 8:30-3pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$40,315"}]}]}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":[332]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Preschool"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph"}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[332]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Morning (Mon-Fri, 8:30-12pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$27,500"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[332]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Full Day (Mon-Fri, 8:30-3pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$36,620"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"2026-27 Language Program"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":[248]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Day Program plus Language Program "}]},{"type":"paragraph"}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph"}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[248]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Toddler (Mon-Fri, 8:30-6pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$58,745*"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[248]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Preschool (Mon-Fri, 8:30-6pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$53,280*"}]}]}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":[248]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Language Program Only"}]},{"type":"paragraph"}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph"}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[248]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Toddler (Mon-Fri, 3-6pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$19,480"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[248]},"content":[{"type":"paragraph","content":[{"type":"text","text":"Preschool (Mon-Fri, 3-6pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$17,710"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"*Discounted Language/Rainbow Room program tuition applies to students enrolled in both the Morning & Afternoon Programs."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"2026-27 School Age Mandarin Program "}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[299]},"content":[{"type":"paragraph","content":[{"type":"text","text":"1st-4th Grade Program (2 Days, 3-6pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$7,000"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[299]},"content":[{"type":"paragraph","content":[{"type":"text","text":"1st-4th Grade Program (3 Days, 3-6pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$10,500"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":[299]},"content":[{"type":"paragraph","content":[{"type":"text","text":"1st-4th Grade Program (5 Days, 3-6pm)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$16,000"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Bus Pick-Up Fee"}]},{"type":"paragraph","content":[{"type":"text","text":"If your child buses from a Cambridge Public School to CES for the Language Program, there is an additional fee to cover their pick up and childcare till programming begins at 3pm. Bus pick-up fees are based on the CPS busing schedule and are calculated individually for each family who participates in the program. The fee typically falls within the range of $525-$825 per school year. "}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"2026-27 Early Bird Care "},{"type":"text","marks":[{"type":"italic"}],"text":"(Limited Enrollment)"}]},{"type":"paragraph","content":[{"type":"text","text":"Early Bird Care (Mon-Fri, 8-8:30am) $3,200"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"For any questions regarding tuition, bus pick-up fees, and financial aid, please contact our Business Manager, Andy Griswold at Andy@Cambridge-Ellis.org."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"Tq9tLv9l,zN5HqFrg,m6s3jp40,t2KeOizQ,m6s3dvs3,l0hT0sPk"}'::jsonb),
  (public.ces_uuid('page_sections', '170aeb94-05ca-42ee-befb-15b71d78c305:add_content:0'), '170aeb94-05ca-42ee-befb-15b71d78c305:add_content:0', public.ces_uuid('pages', '170aeb94-05ca-42ee-befb-15b71d78c305'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Deposits for the 2025-26 school year are due by March 17, 2025."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Deposits are "},{"type":"text","marks":[{"type":"bold"}],"text":"non-refundable "},{"type":"text","text":"unless the enrolling family has submitted a written, dated, and signed statement withdrawing the student\u2019s enrollment to the Director of Admissions by March 15, 2025.\u00a0The deposit will be credited toward the Student\u2019s tuition obligation for the 2025-26 school year."}]}]},{"type":"paragraph"}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"BNj6dIiV"}'::jsonb),
  (public.ces_uuid('page_sections', '170aeb94-05ca-42ee-befb-15b71d78c305:add_content:1'), '170aeb94-05ca-42ee-befb-15b71d78c305:add_content:1', public.ces_uuid('pages', '170aeb94-05ca-42ee-befb-15b71d78c305'), null, 'text', 2, false, '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Please use the following link to submit deposits for the 2024-25 School year."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://bngn.blackbaud.school/?id=yrwunmzuxfg#/home/","rel":null,"target":null,"title":null}},{"type":"bold"}],"text":"2024-25 Tuition Deposits"}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"OR52n05c"}'::jsonb),
  (public.ces_uuid('page_sections', 'b131b608-32c3-4073-9050-ebf8b6c9dc7f:add_content:0'), 'b131b608-32c3-4073-9050-ebf8b6c9dc7f:add_content:0', public.ces_uuid('pages', 'b131b608-32c3-4073-9050-ebf8b6c9dc7f'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cambridge-Ellis School has a history of helping families make an independent preschool education possible for their children. We currently dedicate approximately 10% of our tuition revenue towards scholarships."}]},{"type":"paragraph","content":[{"type":"text","text":"Fundamentally, financial aid enriches the Cambridge-Ellis community by bringing together families from many backgrounds and experiences. We believe education and lifelong friendships forged at the school should be accessible to students of all economic backgrounds."}]},{"type":"paragraph","content":[{"type":"text","text":"Cambridge-Ellis is proud to use the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://auth.clarityapp.com/en/signup/","rel":null,"target":"_blank","title":null}},{"type":"bold"}],"text":"Clarity Application"},{"type":"text","text":" to determine a family\u2019s level of financial need based on the information that families share in the application, which includes assets, income, expenses, and debts."}]},{"type":"paragraph","content":[{"type":"text","text":"To get started, please go to the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://auth.clarityapp.com/en/signup/","rel":null,"target":"_blank","title":null}},{"type":"bold"}],"text":"Clarity Application"},{"type":"text","text":" and create an account. The application typically takes less than 30 minutes to complete. The Clarity Application is also mobile-friendly, so you can complete it from anywhere. You are also able to save your progress and return at any time. At the end of the application, there is a $65 fee to submit, and you can share your application with additional schools that accept the Clarity Application for no additional charge. Simply use the dropdown menu in the application to select those schools."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"For any questions regarding financial aid, please contact our Business Manager Andy Griswold at "},{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:andy@cambridge-ellis.org","rel":null,"target":null,"title":null}},{"type":"italic"}],"text":"Andy@Cambridge-Ellis.org"},{"type":"text","marks":[{"type":"italic"}],"text":"."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"JgCUlm58,DVqHXD0M"}'::jsonb),
  (public.ces_uuid('page_sections', '95e957e5-9cd2-4652-a6ef-662b38a19d8d:add_content:0'), '95e957e5-9cd2-4652-a6ef-662b38a19d8d:add_content:0', public.ces_uuid('pages', '95e957e5-9cd2-4652-a6ef-662b38a19d8d'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To receive information about Cambridge Ellis School, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://cambridge-ellis.myschoolapp.com/app/embed#inquiry/40349","rel":null,"target":"_blank","title":null}}],"text":"please complete the form here"},{"type":"text","text":". If you have immediate questions about the school or the admission process, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/contact","rel":null,"target":null,"title":null}}],"text":"contact the Admission Office"},{"type":"text","text":"."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '6d48eb1a-4eb4-48b0-a408-df269842f815:add_content:0'), '6d48eb1a-4eb4-48b0-a408-df269842f815:add_content:0', public.ces_uuid('pages', '6d48eb1a-4eb4-48b0-a408-df269842f815'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One of the things that makes the Cambridge-Ellis School experience so special is the myriad ways families can invest in the school. Depending on what feels right to your family, you can contribute to the CES community by volunteering on a board or school committee, working with the Community Builders on fun events throughout the year, and contributing to the Cambridge-Ellis Annual Fund and annual spring Auction event.\u00a0"}]},{"type":"paragraph","content":[{"type":"text","text":"You may receive a request for additional, direct financial support on a few occasions. You\u2019ll hear from the Development Committee during our Annual Fund drive in the fall (we are so proud that we have met our 100% participation goal for several years in a row, thanks to our incredible community!) and the Auction in the spring. The Community Builders organize a collection for faculty and staff gifts during the winter holiday season."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"ZOPtQhAD"}'::jsonb),
  (public.ces_uuid('page_sections', '2d2dfb77-be33-43a8-8b81-ea5fb25d09f3:add_content:0'), '2d2dfb77-be33-43a8-8b81-ea5fb25d09f3:add_content:0', public.ces_uuid('pages', '2d2dfb77-be33-43a8-8b81-ea5fb25d09f3'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Volunteerism "}]},{"type":"paragraph","content":[{"type":"text","text":"Volunteer participation benefits all of our families, children, and staff and is an essential component of the Cambridge-Ellis community. Families will receive a volunteer interest survey in the spring for volunteer involvement the following school year.\u00a0 "}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Community Builders"},{"type":"text","text":" (formerly the Parent Teacher Association)"}]},{"type":"paragraph","content":[{"type":"text","text":"The Community Builders begin forming committees and planning in the first weeks of the school year.\u00a0 Family involvement is voluntary with several options for the level of time commitment, from co-chairing a committee to donating baked goods for a classroom birthday party."}]},{"type":"paragraph","content":[{"type":"text","text":"To learn more about the work of our Community Builders, reach the committee chair Jess Tangren at pta@cambridge-ellis.org"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Board Committee Work"}]},{"type":"paragraph","content":[{"type":"text","text":"To learn more about the work of our Board Committees, reach out to the Board Co-Chairs Hilary Rasmussen and Rahul Khara at cochairs@cambridge-ellis.org."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Classroom Collaboration"}]},{"type":"paragraph","content":[{"type":"text","text":"To learn more about or share ideas for classroom collaboration, reach out to your child''s classroom teachers."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Gifts"}]},{"type":"paragraph","content":[{"type":"text","text":"Financial support in all amounts is welcomed. Financial gifts will support the financial aid needs of our community through tuition assistance for families, professional development opportunities for our faculty, as well as the many costs of running a school not fully covered by our tuition. Gifts to Cambridge-Ellis can be made in the following ways:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Checks"},{"type":"hardBreak"},{"type":"text","text":"All gifts should be made payable to Cambridge-Ellis School. Our mailing address is: Cambridge-Ellis School, 80 Trowbridge Street, Cambridge, MA 02138"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Online Giving"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/donate","rel":null,"target":null,"title":null}}],"text":"Click here to donate to CES."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Matching gifts"},{"type":"hardBreak"},{"type":"text","text":"Many corporate companies are willing to match a gift to an organization of your choice. Contact your personnel office to see if your employer is willing to match your gift to Cambridge-Ellis."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Securities"},{"type":"hardBreak"},{"type":"text","text":"Gifts of securities may be made in various ways. Please check with your bank, broker or agent about their procedures if you are interested in transferring a gift of securities. To facilitate a gift of stock, please contact Andy Griswold in the Business Office, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:andy@cambridge-ellis.org","rel":null,"target":null,"title":null}}],"text":"Andy@Cambridge-Ellis.org"},{"type":"text","text":".\u00a0"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"For other ways to support our school, please contact us\u00a0at\u00a0"},{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:development@cambridge-ellis.org","target":null,"rel":null}},{"type":"italic"}],"text":"development@cambridge-ellis.org"},{"type":"text","marks":[{"type":"italic"}],"text":"."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"KjBsDA9C,CW0Hwlan,rKazQNHg"}'::jsonb),
  (public.ces_uuid('page_sections', '2bb91e42-3c1d-4e5d-b864-467efadb8d58:add_content:0'), '2bb91e42-3c1d-4e5d-b864-467efadb8d58:add_content:0', public.ces_uuid('pages', '2bb91e42-3c1d-4e5d-b864-467efadb8d58'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Our tuition gap ranges annually from 8-10%, and donor contributions are crucial to meeting the school\u2019s budgetary goals. Our goal is to get 100% participation in the Annual Fund from our board members, parent community, faculty, and staff every year, with additional support from alumni families, grandparents, and friends.\u00a0 Donations can range from $1 to $20,000."}]},{"type":"paragraph","content":[{"type":"text","text":"At Cambridge-Ellis School, we encourage each member of the community to contribute to our annual fund goals. The Annual Fund supports general operations in the following ways:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Offsets the budgetary gap between tuition and school expenses"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Provides financial aid scholarships"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Maintains building & grounds and funds capital improvements"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Supports professional development for our educators"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"We strive for 100% community participation, which demonstrates the strength of community in our constituents and provides a solid base for furthering our fundraising opportunities. Our annual giving is made up of a collective group that includes:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Current families"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Alumni families"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Faculty & Staff"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Grandparents"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Friends"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Maintaining the annual fund is fundamentally important to Cambridge-Ellis and the high community participation rate illustrates the wonderful community support for the school. "}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Your Support of the Cambridge-Ellis Annual Fund:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Invests in Excellence: Professional Development and Enrichment"}]},{"type":"paragraph","content":[{"type":"text","text":"CES fuses a warm and caring environment with a child-focused curriculum. Teacher quality is a key driver of student success. The school provides time away from the classroom and funding for our educators to attend and present at national conferences on early childhood education."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Promotes Diversity: Financial Aid Scholarships"}]},{"type":"paragraph","content":[{"type":"text","text":"Our efforts to increase access and inclusion across the CES community means ensuring financial aid support for socioeconomically diverse families. Our financial aid offerings increased by 22% over the last five years thanks to CES Annual Fund supporters and donations.\u00a0"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Protects Our Future: Capital Improvements and Future Fiscal Health"}]},{"type":"paragraph","content":[{"type":"text","text":"CES is a non-profit school with a legacy of over forty years of providing exceptional education and care to our children. Through the years, active Board and parent involvement has included fundraising initiatives that enabled our school to persevere through challenging times. Our children enjoy the benefits of past philanthropic efforts every day: Donations from past families have allowed us to make substantial building updates, from installing modern HVAC equipment\u00a0 to adding new energy efficient windows on the second floor. \u00a0In the summer of 2024, we built a completely new design for our toddler playground area and made repairs to our large playground space which is a rarity for a school in urban Cambridge.\u00a0"}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"MNlnEpZy,cZgDdmZL,oNbEV0H5"}'::jsonb),
  (public.ces_uuid('page_sections', '7c9e5336-9d8b-40d0-b884-0e0e0712dcff:add_content:0'), '7c9e5336-9d8b-40d0-b884-0e0e0712dcff:add_content:0', public.ces_uuid('pages', '7c9e5336-9d8b-40d0-b884-0e0e0712dcff'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Cambridge-Ellis School\u2019s annual auction has been a central fundraising event and part of the CES fabric since the earliest years of the school. The auction is a community-building event that brings current parents, teachers, staff, and alumni families together to celebrate the school and support our financial aid and educational programs. After transforming to a virtual event for two years during the pandemic, the Auction returned to CES for the celebration of our 40th anniversary, and was held in 2024 at the Community Rowing Harry Parker Boathouse in Brighton."}]},{"type":"paragraph","content":[{"type":"text","text":"The festive evening is a chance for the CES community of families, educators, and friends to gather, enjoy delicious food and drink, and bid on classroom created artworks and unique CES experiences. The generosity of our community, auction item donors, and event sponsors helps us meet our fundraising goals and support our robust financial aid program."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"rKTGfMz5,jM2VH7vk"}'::jsonb),
  (public.ces_uuid('page_sections', '7c9e5336-9d8b-40d0-b884-0e0e0712dcff:add_content:2'), '7c9e5336-9d8b-40d0-b884-0e0e0712dcff:add_content:2', public.ces_uuid('pages', '7c9e5336-9d8b-40d0-b884-0e0e0712dcff'), null, 'text', 2, false, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://e.givesmart.com/events/xXk/","rel":null,"target":null,"title":null}}],"text":"2024-25 Auction and Celebration tickets are now available for purchase!"}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"lg5953ca"}'::jsonb),
  (public.ces_uuid('page_sections', '4ab4d443-e760-4025-8d59-be82badb9f10:donate_template_copy:0'), '4ab4d443-e760-4025-8d59-be82badb9f10:donate_template_copy:0', public.ces_uuid('pages', '4ab4d443-e760-4025-8d59-be82badb9f10'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Donate to Cambridge-Ellis"}]},{"type":"paragraph","content":[{"type":"text","text":"Thank you for considering donating to Cambridge-Ellis! Your support helps us continue in our mission to enrich the lives of those we care for."}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"promoted_from":"resources/views/donate.antlers.html"}'::jsonb),
  (public.ces_uuid('page_sections', '80db4d25-4d83-49ad-8d90-62f26c47a7b9:add_content:0'), '80db4d25-4d83-49ad-8d90-62f26c47a7b9:add_content:0', public.ces_uuid('pages', '80db4d25-4d83-49ad-8d90-62f26c47a7b9'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We appreciate your interest in Cambridge-Ellis School! Please reach out to us with any questions you may have."}]},{"type":"paragraph","content":[{"type":"text","text":"Please also visit our "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/contact/frequently-asked-questions","rel":null,"target":null,"title":null}}],"text":"Frequently Asked Questions"},{"type":"text","text":" Page for more information."}]},{"type":"paragraph","content":[{"type":"text","text":"Address:"},{"type":"hardBreak"},{"type":"text","text":"80 Trowbridge St, Cambridge, MA 02138"}]},{"type":"paragraph","content":[{"type":"text","text":"Phone:"},{"type":"hardBreak"},{"type":"text","text":"(617) 354-0014"}]},{"type":"paragraph","content":[{"type":"text","text":"Fax:"},{"type":"hardBreak"},{"type":"text","text":"(617) 491-4313"}]},{"type":"paragraph","content":[{"type":"text","text":"Email:"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:Info@Cambridge-Ellis.org","rel":null,"target":null,"title":null}}],"text":"Info@Cambridge-Ellis.org"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Head of School, Bekah Riley"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:Bekah@Cambridge-Ellis.org","rel":null,"target":null,"title":null}}],"text":"Bekah@Cambridge-Ellis.org"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Director of Education, Lindsey Freedman"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:Lindsey@Cambridge-Ellis.org","rel":null,"target":null,"title":null}}],"text":"Lindsey@Cambridge-Ellis.org"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Language Program Director, Elisabeth Guenette"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:Elisabeth@Cambridge-Ellis.org","rel":null,"target":null,"title":null}}],"text":"Elisabeth@Cambridge-Ellis.org"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Director of Admissions, Christina Isidoro"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:Christina@Cambridge-Ellis.org","rel":null,"target":null,"title":null}}],"text":"Christina@Cambridge-Ellis.org"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Business Manager, Andy Griswold"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:Andy@Cambridge-Ellis.org","rel":null,"target":null,"title":null}}],"text":"Andy@Cambridge-Ellis.org"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Director of Development, Alex Danton-Klein"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:Alex@Cambridge-Ellis.org","rel":null,"target":null,"title":null}}],"text":"Alex@Cambridge-Ellis.org"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Arts Coordinator, Katie Clark"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:Katie@Cambridge-Ellis.org","rel":null,"target":null,"title":null}}],"text":"Katie@Cambridge-Ellis.org"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Office Manager, Michelle Phoenix"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:Michelle@Cambridge-Ellis.org","rel":null,"target":null,"title":null}}],"text":"Michelle@Cambridge-Ellis.org"}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{"set_id":"8k7vQuWS"}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:add_content:0:prose:0'), '72301430-4743-448d-8a1f-70552c3c25eb:add_content:0:prose:0', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'text', 1, true, '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Language Program"}]}]}'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:0'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:0', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 2, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q:  What is the language program experience like at Cambridge-Ellis?', 'A: At Cambridge Ellis, our students have the opportunity to learn Spanish, French, and Mandarin in an immersive, play-based environment focused on open-ended exploration and emergent curriculum stemming from the interests of the children.  ', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:1'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:1', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 3, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: How do teachers work with such a broad range of ages?', 'A: Children ages 2.9 to 6 learn language together in the classroom. The advantage of this model is that the oldest children use and model language, skills, and understanding of concepts for the younger children, who in turn benefit from watching and learning from and with their classmates as they navigate the different activities together. Teachers individualize their support and language learning activities and sometimes break into small groups to meet the language and developmental needs of the children.', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:2'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:2', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 4, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: How does the language program differ from the day program?', 'A: The Language Program is similar to the Day Program in terms of philosophy (play-based, emergent curriculum, exploratory hands-on learning), but classroom time is shorter (three hours, four days a week), and the age range of the children in each classroom is larger (2.9 years – 6 years). ', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:3'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:3', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 5, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: Does your child need to speak the language before starting the program? ', 'A: No, children do not need a prior knowledge base before entering the program. In each classroom, there are children who have never heard or spoken the language before, children who have one or more family members who speak the language with them at home, and some who have differing amounts of prior exposure.', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:4'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:4', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 6, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: How does the program handle differences in skill levels?', 'A: In each classroom there is a considerable amount of whole group experience so that children of all skill levels can come together and feel a sense of community and belonging in the classroom. The teachers also separate the children into small groups to individualize the immersion experience and make sure more linguistically advanced children are challenged while less experienced children get the building blocks they need to learn the language. As children become more experienced in the language, their vocabulary grows, so teachers build on that vocabulary gradually.', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:5'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:5', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 7, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: Does Cambridge-Ellis tackle reading and writing skills in addition to speaking?', 'A: It varies. For children at the top of the age range who are learning reading and writing in school, the Language Program reinforces these skills in Spanish, French, and Mandarin. However, we don’t use worksheets or use explicit instruction in these areas. Instead, the teachers use games and interactive activities to promote an understanding of sounds, characters, letters, and words.', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:6'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:6', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 8, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: What are the benefits of having my child learn a foreign language?', 'A: Young children can learn a language (including vocabulary, sentence structure, pronunciation, and cultural contexts) very quickly. In fact, they can learn more than one language at a time. There is a large body of research indicating that learning a foreign language as a young child has a positive impact on brain development, such as developing stronger problem solving skills. Think of the brain as a muscle that is being exercised when engaging with foreign language. Additionally, learning a foreign language helps children broaden their cultural understanding and develop empathy, kindness, and compassion.', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:7'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:7', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 9, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: Is there any way for my child to take more than one language throughout the year?', 'A: No. A key goal of the program is for children to move toward fluency, which requires time hearing and practicing the language on a consistent basis. However, the children do get exposure to the other classroom languages through language-program-wide events and weekly assemblies.', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:8'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:8', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 10, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: What activities do language program students have access to?', 'A: As in our Day Program, Language Program students participate in music, Arts Adventure, nature programming, weekly assemblies, games and activities, cooking, playground time, and circle time — to name just a few!', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:9'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:9', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 11, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: Can my child be a part of the language program without enrolling in the day program?', 'A: Absolutely! Priority is given to children already enrolled at Cambridge-Ellis during the day, but there are often open spots for new families whose children do not attend the Day Program.', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:10'), '72301430-4743-448d-8a1f-70552c3c25eb:faq_item:10', public.ces_uuid('pages', '72301430-4743-448d-8a1f-70552c3c25eb'), null, 'faq_item', 12, true, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Q: Can my child take a bus from a Cambridge Public School to the afternoon Language Program?  ', 'A: Yes, we pick up children at their various bus stops and escort them to Cambridge-Ellis.  Since the buses do not drop children right at the school, we need to have a sufficient number of staff who can leave CES to pick up children. Please talk with the Language Program Director if you have questions regarding bus pick up.', '{}'::jsonb, '{}'::jsonb),
  (public.ces_uuid('page_sections', '21904ad8-20a4-4672-a6eb-51204901e0e7:sessions:0:programs_in_this_session:0'), '21904ad8-20a4-4672-a6eb-51204901e0e7:sessions:0:programs_in_this_session:0', public.ces_uuid('pages', '21904ad8-20a4-4672-a6eb-51204901e0e7'), public.ces_uuid('page_sections', '21904ad8-20a4-4672-a6eb-51204901e0e7:sessions:0'), 'program', 1, true, null, null, null, null, null, null, null, null, null, null, null, '8:30 - 12pm, $2400', '8:30 - 4pm, $2750', '8:30 - 5pm, $3150', null, null, null, null, '{"half_day_label":"Half day: ","full_day_label":" Full day: ","extended_day_label":"Extended day: "}'::jsonb, '{"set_id":"voiW3WLF"}'::jsonb)
insert into public.people
  (id, legacy_ref, slug, name, official_title, joined_ces, email, bio, photo_asset_id, published, sort_order, legacy, source_updated_at, source_updated_by)
values
  (public.ces_uuid('people', '7155850a-b6ed-4491-a59f-be71de8ba8a2'), '7155850a-b6ed-4491-a59f-be71de8ba8a2', 'aaron-paul', 'Aaron Paul', 'Buildings and Grounds Committee Chair', null, 'abcpaul@gmail.com', null, public.ces_uuid('assets', 'aaron-paul.jpg'), true, 1, '{"blueprint":"people"}'::jsonb, '2025-09-18T13:45:57.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '42675d8c-d572-4c5a-83d1-d8576f089a35'), '42675d8c-d572-4c5a-83d1-d8576f089a35', 'alex-danton-klein', 'Alex Danton-Klein', 'Director of Development', '2025-08-22'::date, 'Alex@Cambridge-Ellis.org', 'As the Development Director, I work on a number of exciting projects, from our Annual Fund that supports completing our budget, to our auction in the spring, from alumni outreach to fostering a sense of connection and community with all families. Prior to joining the Cambridge-Ellis School, I have a long history of working in environmental education, managing farm-based learning programs for toddlers through teens. If you ever want to chat with me about gardening or growing food, I’m your gal! I am a beekeeper and a fiber artist, and when I’m not working on those projects or at school, you can find me walking my two dogs around Cambridge, or playing with my 6-month old son.', public.ces_uuid('assets', '2025-26-alex-head-shot.png'), true, 2, '{"blueprint":"people","education_without_institution":[{"id":"mfd1khga","type":"institution","enabled":true}]}'::jsonb, '2025-09-18T13:31:16.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '06f57a4f-cabc-45fa-a356-d2d9d3c079d1'), '06f57a4f-cabc-45fa-a356-d2d9d3c079d1', 'amanda-obremski', 'Amanda Obremski', 'Green Room Co-Head Teacher', '2011-09-01'::date, 'Amanda@Cambridge-Ellis.org', 'I feel very fortunate to be a Green Room teacher at Cambridge Ellis for the past 13 years. I knew I wanted to work at Cambridge Ellis from the moment I stepped through the door because of the warm, nurturing, and play-based environment that fosters learning and creativity for children through real-life experiences and material exploration. CES has become a second home for me and I feel so honored to learn and grow alongside your children every day.', public.ces_uuid('assets', 'amanda-headshot.png'), true, 3, '{"blueprint":"people","classrooms":["9ae28b20-3a65-4e4b-8f56-4de6eef458f9"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:44:32.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '1c1cc7a8-4625-4982-a995-8044af5878cd'), '1c1cc7a8-4625-4982-a995-8044af5878cd', 'an-fong', 'An Fong', 'Floating Teacher', '2015-07-01'::date, 'An@Cambridge-Ellis.org', 'After receiving my teaching degree from South China Normal University in early education, I taught kindergarten in China for four years. In 1997 I moved to the US and taught Chinese Mandarin to young children for over a decade. At CES I taught an additional 9 plus years as teacher/co-head teacher. My husband and I raised two daughters who are now out of college and well on their way to chasing down their dreams. I am excited to now support this community as a floating teacher. I love having the opportunity to work with your children every day and am so happy to be a part of the Cambridge-Ellis community!', public.ces_uuid('assets', 'an-headshot.png'), true, 4, '{"blueprint":"people","classrooms":["1bdc622f-5bcd-4d93-ab82-89cac9bc1b49"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:45:00.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'e1cb2b8e-7150-465b-b287-0f00c9ae794b'), 'e1cb2b8e-7150-465b-b287-0f00c9ae794b', 'andrea-connelly', 'Andrea Connelly', 'Spanish Teacher', '2025-08-22'::date, 'Andrea@Cambridge-Ellis.org', 'I''m from Colombia, and I moved to Massachusetts at the end of 2022. My native language is Spanish, and I''m passionate about education. I have a bachelor''s degree in Physics and am currently pursuing a master''s degree in the same field. I am excited to bring my curiosity, creativity, and passion for learning to the preschool classroom. I hope to help our students discover Spanish through songs, stories, science, and games. In my free time, I enjoy crocheting and spending time with my husband and dog. I''m excited to be part of the CES community and begin this new adventure with the students.', public.ces_uuid('assets', '2025-26-andrea-head-shot.jpg'), true, 5, '{"blueprint":"people"}'::jsonb, '2025-09-09T20:19:52.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '7154caac-857b-4f19-8489-96fa5cd2edbd'), '7154caac-857b-4f19-8489-96fa5cd2edbd', 'andy-griswold', 'Andy Griswold', 'Business Manager', '2018-12-03'::date, 'Andy@Cambridge-Ellis.org', 'I am very happy to support the wonderful early childhood education program  at Cambridge-Ellis as the Business Manager. After a first career in the private sector, I entered the nonprofit world in 2002 as the Business Manager for St. Paul’s Parish, St. Paul’s Choir School, and the Harvard Catholic Center. I joined CES in 2018 and look forward to more years serving our children and families.  My wife and I are long time residents of Medford and we are connected to Cambridge through CES and also through our parish of St. Paul’s where we enjoy singing in the choir.', public.ces_uuid('assets', 'Andy Griswold.jpg'), true, 6, '{"blueprint":"people","template":"bio"}'::jsonb, '2025-02-11T19:45:39.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '8e1241f8-042f-4dcf-85f7-7ba29f331650'), '8e1241f8-042f-4dcf-85f7-7ba29f331650', 'annie-underwood', 'Annie Underwood', 'Floating Teacher', '2025-08-22'::date, 'Annie@Cambridge-Ellis.org', 'I grew up in Holliston, Massachusetts, where I attended public schools, and also had the unique opportunity to spend part of high school studying at an all-girls academy in Toorak, Australia. I later earned my degree in Cultural Anthropology and Women & Gender Studies from Santa Clara University in California, and spent time studying Human Rights and Multiculturalism in Rabat, Morocco. Since moving back to Cambridge, I’ve discovered how much I love working with young children. I’ve had the joy of teaching in extended day, summer, and substitute roles at The Shady Hill School, and most recently spent a year as an Associate Teacher at Fayerweather Street School. When I’m not in the classroom, I enjoy painting, biking around the city, and practicing yoga and meditation with friends.', public.ces_uuid('assets', '2025-26-annie-head-shot.jpg'), true, 7, '{"blueprint":"people"}'::jsonb, '2025-09-09T20:24:26.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'a7453a82-54e3-4ff3-8936-927e77945555'), 'a7453a82-54e3-4ff3-8936-927e77945555', 'ashley-green', 'Ashley Green', 'Board Co-Chair', null, 'ashelyegreen2019@gmail.com', null, public.ces_uuid('assets', 'ashley-green-headshot.JPG'), true, 8, '{"blueprint":"people"}'::jsonb, '2025-07-15T15:05:53.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'c237bba1-b7af-4e30-81ac-50072b37ef9f'), 'c237bba1-b7af-4e30-81ac-50072b37ef9f', 'bekah-riley', 'Bekah Riley', 'Head of School; Leadership Board Representative', '2018-08-24'::date, 'Bekah@Cambridge-Ellis.org', 'After graduating from Dartmouth College with a degree in Studio Art and Education, I joined Teach for America. I spent two years teaching bi-lingual preschool in Delaware, where I gained a passion for bringing topics of social justice into the early childhood sphere. I am a native of upstate New York and spent several years teaching at and directing a small, nature-based, cooperative preschool there. After moving to Boston with my husband and two cats, I was lucky enough to find a forever home in CES. As the Executive Director, my role is to support teachers as they facilitate student-led learning through discovery and play, and caregivers as they embark on their child''s first school experience.', public.ces_uuid('assets', '7566a0ee-8434-4779-b3e2-2b4a338bbf85.jpeg'), true, 9, '{"blueprint":"people","template":"bio"}'::jsonb, '2025-09-09T21:14:34.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '13b18063-e959-439e-84e0-936fc2d97c8e'), '13b18063-e959-439e-84e0-936fc2d97c8e', 'bobby-shady', 'Bobby Shady', 'Board Member', null, 'robert.shady@gmail.com', null, public.ces_uuid('assets', 'bobby-shady.jpg'), true, 10, '{"blueprint":"people"}'::jsonb, '2025-09-18T13:49:41.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'e8ac136c-ebf2-485a-9240-f3233bad51e7'), 'e8ac136c-ebf2-485a-9240-f3233bad51e7', 'caroline-fry', 'Caroline Fry', 'Co-Head French Teacher; Board Faculty Representative', '2025-08-22'::date, 'Caroline@Cambridge-Ellis.org', 'Originally from Lyon, France, I moved to the U.S. to start a family and raise my three children. I studied foreign languages (English, German, and Italian) in college and later became a certified EEC teacher. For the past few years, I''ve loved teaching French to children (18 months to 12 years) through both mother-tongue and immersion programs, celebrating each child''s uniqueness and fostering creativity in a nurturing environment. Passionate about art, music, puppetry, and children''s literature, I incorporate these daily in my classroom to spark imagination, build language skills, and encourage empathy. Outside of teaching, I enjoy traveling, photography, swimming, reading, and spending time with loved ones—passions that inspire my joyful and creative approach to education.', public.ces_uuid('assets', '2025-26-caroline-head-shot.jpg'), true, 11, '{"blueprint":"people"}'::jsonb, '2025-12-31T20:50:08.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'cc72ac48-e946-4e08-bd5d-4067afa5fe87'), 'cc72ac48-e946-4e08-bd5d-4067afa5fe87', 'carolyn-olshan', 'Carolyn Olshan', 'Auction Committee Chair', null, 'carolyn.b.olshan@gmail.com', null, public.ces_uuid('assets', 'carolyn-olshan-headshot.JPG'), true, 12, '{"blueprint":"people"}'::jsonb, '2025-07-15T14:35:53.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'fb148191-0943-43e6-912c-a201bad7dae8'), 'fb148191-0943-43e6-912c-a201bad7dae8', 'charlotte-pride', 'Charlotte Pride', 'Co-Head French Teacher; Faculty Board Representative', '2024-08-23'::date, 'Charlotte@Cambridge-Ellis.org', 'As a native of France with over two decades of international experience, I bring a passion for cultural exchange and language education to Cambridge-Ellis School. I am excited to combine my native French fluency, cultural expertise, and passion for teaching young learners to become confident global citizens. When not in the classroom, you''ll find me in the kitchen (baking bread or cooking meals for friends and family), skiing with my family (husband and three children), cycling, or taking walks with our dog Zoé.', public.ces_uuid('assets', '2025-26-charlotte-head-shot.jpg'), true, 13, '{"blueprint":"people"}'::jsonb, '2025-09-09T20:32:11.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '70683307-d0b0-4e8e-b4bf-2bae5c3a0167'), '70683307-d0b0-4e8e-b4bf-2bae5c3a0167', 'christina-hanley', 'Christina Hanley', 'Rainbow Co-Head Teacher', '2024-08-23'::date, 'Christinahanley@Cambridge-Ellis.org', 'After a few years working in preschool and kindergarten Special Education classrooms, I am passionate and experienced in early childhood. With a B.S. in Counseling from Lesley University, I feel I bring a well-rounded perspective of early childhood development to the classroom, and I strive to help each and every child grow and learn in their own way. I have a background in art and love bringing it into my classroom in any way I can, encouraging students to have sensory experiences and learn along the way. I love to cook and spend time outside, and I love to experience the world the way our kids do, with curiosity and open-mindedness. I am excited to be a part of the CES team!', public.ces_uuid('assets', 'christina-hanley.jpeg'), true, 14, '{"blueprint":"people"}'::jsonb, '2025-07-23T18:02:45.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'c2f68fc6-2439-4912-a545-f520fcd8dadb'), 'c2f68fc6-2439-4912-a545-f520fcd8dadb', 'christina-isidoro', 'Christina Isidoro', 'Director of Admissions', '2008-06-11'::date, 'Christina@Cambridge-Ellis.org', 'As soon as I walked into Cambridge-Ellis for the first time, I realized this was a very special place. I began working at CES the Summer of 2008 as a toddler teacher and never looked back! I have taught in many CES classrooms over the years, and I’ve had the wonderful privilege of providing all four of my children the opportunity to grow here as well. I just had to share this experience with the wider community, and as the Associate Director of Admissions, I get to do exactly that! My family is very important to me, so when I’m not at CES I soak up every moment with my husband and four children.', public.ces_uuid('assets', 'christina-isidoro.jpeg'), true, 15, '{"blueprint":"people","template":"bio"}'::jsonb, '2025-09-09T21:16:01.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'e00d8cf8-bb4a-46e4-aa49-7b8579ce1fda'), 'e00d8cf8-bb4a-46e4-aa49-7b8579ce1fda', 'cindy-lehmann', 'Cindy Lehmann', 'Purple Room Co-Head Teacher', '2011-08-31'::date, 'Cindy@Cambridge-Ellis.org', 'With three decades of teaching experience in early childhood programs, I was impressed with the quality of care and professionalism that I observed when I came to CES. I knew it was a place where I could continue to grow as an educator. I love working with the four and five year olds as they explore and discover their world and share their thoughts and insights. Outside of work, I enjoy spending time with my husband and basically grown twin daughters. I love to walk, bike, and hike. I have recently taken up pickleball, but I think I will call myself a beginner for a long time.', public.ces_uuid('assets', 'cindy-headshot.png'), false, 16, '{"blueprint":"people","classrooms":["7c58e147-8daa-4bf1-9ef4-0c2d74ac028f"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:47:05.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'd120d817-6a1f-4fac-ab04-8804189991d3'), 'd120d817-6a1f-4fac-ab04-8804189991d3', 'claudia-allevato', 'Claudia Allevato', 'Orange Room Co-Head Teacher, Rainbow Co-Head Teacher', '2001-09-10'::date, 'Claudia@Cambridge-Ellis.org', 'I am proud to be a long-standing member of the Cambridge-Ellis School. Since 2000, I have supported many children from two to four years of age in the Day Program and Rainbow Rooms. As a native speaker of Portuguese, I love to share my language and Brazilian culture with all the children at Cambridge-Ellis. Outside of school, I enjoy my family, cooking, dancing, and spending time with my cat Shana.', public.ces_uuid('assets', 'claudia-headshot.png'), true, 17, '{"blueprint":"people","classrooms":["73f44629-52d8-444e-8cc4-35a3a7569479","a289ada5-75ed-4478-a0ac-457b827c8850"],"programs":["day","language"],"template":"bio"}'::jsonb, '2025-02-11T19:47:46.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'e73d0602-ec2b-4ac2-bdf0-991a63ed9ee6'), 'e73d0602-ec2b-4ac2-bdf0-991a63ed9ee6', 'daniel-kanter', 'Dan Kanter', 'Governance Committee Chair', null, 'daniel.r.kanter@gmail.com', null, public.ces_uuid('assets', 'daniel-kanter-headshot.JPG'), true, 18, '{"blueprint":"people"}'::jsonb, '2025-07-23T16:51:30.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '2f05d078-eb5b-429d-a912-291c0322b790'), '2f05d078-eb5b-429d-a912-291c0322b790', 'dayane-pierre', 'Dayane Pierre', 'Rainbow Red Co-Head Teacher', null, 'Dayane@Cambridge-Ellis.org', 'I have been teaching in Reggio-inspired preschools for over 5 years now in the Cambridge/Somerville area. Since a child, teaching has been my passion. I used to turn the dining area in my house into a classroom and pretend to give my cousins lessons. I moved to the US from Haiti when I was 6 years old and went to school in Cambridge. I enjoy watching children grow and helping them reach their developmental milestones. I am a self-proclaimed foodie and enjoy trying new dishes from different cultures and restaurants around the city. I have a passion for cooking and adding my own Island flavor to any dish I create. I enjoy dancing and listening to music from all different cultures.', public.ces_uuid('assets', 'dayane.png'), false, 19, '{"blueprint":"people"}'::jsonb, '2023-08-14T17:21:20.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '3bb1c2b6-2776-4b43-a958-9dd30c3ceea3'), '3bb1c2b6-2776-4b43-a958-9dd30c3ceea3', 'dee-lyle', 'Dee Lyle', 'Amber Room Co-Head Teacher', '2010-09-07'::date, 'Dee@Cambridge-Ellis.org', 'I joined the CES community in 2010 as a Yellow Room teacher. I love Cambridge-Ellis and being part of a community that supports and encourages children as they explore and develop into problem solvers and community members. I live in Arlington with my daughter, Olivia, who is starting her junior year in college. When I am not at CES, I enjoy spending time with family and friends, hiking, biking, and being on my yoga mat. In 2022, I completed a 200 hour yoga teacher training with Breathe for Change and love to share my love of yoga with children.', public.ces_uuid('assets', 'dee-headshot.jpg'), true, 20, '{"blueprint":"people","classrooms":["eb19cc0e-2314-4252-8f6c-af927cfa0ab2"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:48:24.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'e1eef63c-70fd-46bf-8a52-d565876832dc'), 'e1eef63c-70fd-46bf-8a52-d565876832dc', 'domarie-diaz-sanchez', 'Domarie Diaz Sanchez', 'Co-Head Teacher', '2024-08-23'::date, 'Domarie@Cambridge-Ellis.org', E'I’m from Puerto Rico and have 18 years of experience working with preschool-age children.  My native language is Spanish. I have a bachelor’s degree in Elementary Education as well as a master’s degree in Elementary Education from the University of Ana G Mendez, Puerto Rico. Since moving to Massachusetts, I have continued working as a Spanish immersion school teacher. \n\nI love supporting each child in their own path and always strive to give them the care and resources necessary for their independent growth.', public.ces_uuid('assets', 'domarie-headshot.jpg'), true, 21, '{"blueprint":"people"}'::jsonb, '2025-07-23T17:56:58.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '0dd8615e-e014-42a0-8254-405642a7b31c'), '0dd8615e-e014-42a0-8254-405642a7b31c', 'eileen-edmondson', 'Eileen Edmondson', 'Floating Teacher', null, 'Eileen@Cambridge-Ellis.org', 'I have spent most of my adult life working in Early Childhood Education, and I have over 20 years of experience working in the classroom. I enjoy helping children to develop a solid foundation for lifelong learning, which encompasses their social, emotional, cognitive and physical needs. I look forward to helping the children and teachers here to have new, meaningful experiences. Outside of school, I enjoy spending time with my husband, children, and grandchildren as well as cooking Jamaican dishes and watching the Patriots, Celtics, and the Red Sox.', public.ces_uuid('assets', 'Eileen Edmondson.jpg'), false, 22, '{"blueprint":"people","programs":["day"],"template":"bio"}'::jsonb, '2021-10-25T15:08:48.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '2a9c0592-e852-4a9f-8894-532ad4e08e0e'), '2a9c0592-e852-4a9f-8894-532ad4e08e0e', 'elisabeth-guenette', 'Elisabeth Guenette', 'Language Program Director', '2018-08-24'::date, 'Elisabeth@Cambridge-Ellis.org', E'The seeds of my love for languages were planted at an early age through exposure to French songs and expressions from family members. My curiosity and interest in languages, cultures, and education continued to grow as I studied French and Primary Education in college before moving to Toulouse, where I, over the course of three years, taught English, pursued a Master’s Degree in Primary Education at a French University, and taught 4th grade (CM1). \n\nBack in the US in 2018, I found my home at Cambridge-Ellis, a place where all the beliefs I held about best practices in education truly come to life, and where languages and cultures mix together in a rich diversity of experiences and language learning. As the Language Program Director, I have the privilege of supporting teachers in building skills through professional development, incorporating DEI learning and best practices in language learning into their curriculum, and helping our diverse learners to blossom. In addition, I focus on the strategic goals and growth of the Language Program, ensuring that we meet the needs of our community for many years to come.', public.ces_uuid('assets', 'Elisabeth Guenette.jpg'), true, 23, '{"blueprint":"people","classrooms":["a446e4db-e4cc-4662-8a14-9b647d6ba7c2"],"programs":["language"],"template":"bio"}'::jsonb, '2025-02-11T19:48:53.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '8a96eea7-b3d3-4240-83ac-ef1b7b38bab3'), '8a96eea7-b3d3-4240-83ac-ef1b7b38bab3', 'enrica-filippi', 'Enrica Filippi', 'Yellow Room Co-Head Teacher', null, 'Enrica@Cambridge-Ellis.org', 'I knew from an early age that nurturing was a calling for me. After attending Clark University for Psychology, I found myself working with children right away, mostly in settings such as after-school and enrichment programs. When planning curriculum, I enjoy including mindfulness through activities that encourage making connections and observing the natural environment. A native Italian with Chinese roots, I value learning about diverse cultures and perspectives, and listening to stories that help to shape knowing. I love how bright and curious toddlers naturally are, and am excited to be working alongside them more extensively. In my free time, I enjoy the outdoors, reading, yoga, and traveling.', public.ces_uuid('assets', '7c74a18d-1055-43e2-a625-242ba7165acf.jpeg'), false, 24, '{"blueprint":"people","classrooms":["c63dac32-3295-4368-bb8a-f4f1e23b718f"],"programs":["language"],"template":"bio"}'::jsonb, '2022-09-13T21:01:39.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '94d52126-ff66-46b3-a3eb-68ba74f9e72e'), '94d52126-ff66-46b3-a3eb-68ba74f9e72e', 'eva-donlan', 'Eva Donlan', 'French Class Teacher', '2022-08-29'::date, 'Eva@Cambridge-Ellis.org', 'I look forward to supporting the Blue Room for the 2024-25 school year while Liz M. is on maternity leave! Since graduating from college in 2021, I’ve worked with infants, toddlers, and lower preschool; I’m thrilled to dip my toes into the world of upper preschool next year! Nature-based learning is something I value deeply and center in my classroom teaching. In my free time I love to trail run, practice yoga, and read next to my corpulent cat, Mr. Pudding.', public.ces_uuid('assets', 'eva-headshot.jpg'), false, 25, '{"blueprint":"people"}'::jsonb, '2025-07-24T17:36:25.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'ed13fae9-51d4-4926-a5b2-a2933038affd'), 'ed13fae9-51d4-4926-a5b2-a2933038affd', 'ginamarie-falk', 'Gina Marie Falk', 'French Room Head Teacher', '2022-11-14'::date, 'GinaMarie@Cambridge-Ellis.org', 'Engaging with others in French is a big, special part of my life, and working with children through the lens of French immersion is a career path that I hold near to my heart. I am energized by students and colleagues alike and believe that together we can foster a creative, kind, and thoughtful environment. One of my biggest goals in the French classroom is to expose children to the vastness of the francophone world – its people, its music, its food, and its diversity. When I am not teaching, you can find me singing in choirs and chamber ensembles all around the greater Boston area, cooking big meals for my friends and family, or having impromptu dance parties. Looking forward to learning and growing with you all in the French Room!', public.ces_uuid('assets', 'gina-marie-headshot.jpg'), false, 26, '{"blueprint":"people"}'::jsonb, '2025-02-11T19:51:16.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '66d44e68-71be-43e4-9fba-85347355aa70'), '66d44e68-71be-43e4-9fba-85347355aa70', 'gwladys-latreme', 'Gwladys Latrémé', 'French Room Co-Head Teacher', null, 'Gwladys@Cambridge-Ellis.org', 'I have lived in Paris for the last 5 years, but I grew up in the south of France. I studied history knowing that I would like to work with children and become a teacher. I then got a master''s degree in education from INSPE Paris. My journey started as a Middle School teacher, however, I enjoy working with children of all ages. I have been teaching French to non-native speakers as a volunteer for a few years and really enjoy helping people discover my language. I am looking forward to creating a nurturing French classroom based on children’s interests and curiosities. An environment that celebrates self-expression and creativity. In my free time, I enjoy reading, traveling and discovering other cultures, spending time with family and friends, and being involved in social justice work.', public.ces_uuid('assets', 'gwladys-latreme---informal-headshot-1708020734.jpg'), false, 27, '{"blueprint":"people"}'::jsonb, '2024-02-15T18:12:20.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'cb1a5038-e967-419b-831d-13fb45969cae'), 'cb1a5038-e967-419b-831d-13fb45969cae', 'halle-katz', 'Halle Katz', 'Coverage Coordinator', '2023-08-29'::date, 'Halle@Cambridge-Ellis.org', 'Working in education as both a teacher and administrator, Halle considers herself a bridge between people and practices that shape inclusive and creative communities. Halle joined Cambridge-Ellis in August 2023, where she has since found a community that shares her passion for play and nature-based early childhood development. A graduate of Brown University, Halle began her career as a college admissions officer at Bentley University, before transitioning to school counseling and youth development at The Steppingstone Foundation; over the span of 3.5 years, Halle coached hundreds of middle and high school students across the city of Boston, as they navigated first-generation pathways to higher education. At the same time, Halle has been teaching dance professionally since 2016. Determined to expand social-emotional literacy and integrate the body into learning, she pivoted to freelance consulting and teaching and now leads movement & mindfulness programs for movers of all ages and abilities across Greater Boston. Most recently, Halle partnered with Open Door Arts to bring to life an adaptive dance program for neurodiverse learners at The Higginson Inclusion School in Roxbury. This year, Halle is thrilled to join her arts academy alma mater, Wellesley Theatre Project, as a choreographer for their 2024-2025 production season. Other teaching residency credits include: JCC Boston, The British International School of Boston, Babson College, Needham Community Education, Temple Aliyah, Dance for All People, The Center at The Heights, and more. Halle holds practitioner certifications from The Embody Lab, Kripalu School of Mindful Outdoor Education, and Brain-Compatible Dance Education Teaching Institute.', public.ces_uuid('assets', 'halle-katz-headshot.jpg'), false, 28, '{"blueprint":"people"}'::jsonb, '2025-02-11T19:51:40.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'c5f5b264-3321-4d94-8116-941075511bb3'), 'c5f5b264-3321-4d94-8116-941075511bb3', 'hilary-lambert', 'Hilary Rasmussen', 'Board Co-Chair', null, 'lambert.hilary@gmail.com', null, public.ces_uuid('assets', 'hillary-rasmussen-headshot.JPG'), false, 29, '{"blueprint":"people"}'::jsonb, '2024-09-27T18:54:19.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '91f0cb69-d693-44ac-9b9f-1dfbc8e3978d'), '91f0cb69-d693-44ac-9b9f-1dfbc8e3978d', 'holly-luck', 'Holly Luck', 'Floating Teacher', '2021-03-17'::date, 'Holly@Cambridge-Ellis.org', 'I began my educational journey when I received my master’s degree and MA DESE license in 1998 and have been teaching children of various ages ever since. I enjoy the preschool age the most and have ample experience with 3–5 year-olds. I love connecting with young children through nature and engaging their learning through hands-on, play-based curriculum. Outside of school, I spend time near the ocean in Revere with my life partner John. My interests are gardening, cooking, yoga, planning vacations, and backyard gatherings.', public.ces_uuid('assets', '2425-holly-headshot.JPG'), true, 30, '{"blueprint":"people","programs":["language"],"template":"bio"}'::jsonb, '2025-02-11T19:27:48.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '7eeffe6b-8ee3-4c8a-b7df-452c9f0f385e'), '7eeffe6b-8ee3-4c8a-b7df-452c9f0f385e', 'janine-robinson', 'Janine Robinson', 'Red Room Teacher', '2007-09-04'::date, 'Janine@Cambridge-Ellis.org', 'I have been teaching for over twenty years! 14 of those wonderful years have been spent here, at Cambridge-Ellis, as both a teacher and a parent. When I’m not teaching, I spend a lot of time with my friends and family. We enjoy exploring parks, visiting museums and eating yummy food together. My favorite thing to do, at all times, is making beautiful, messy art with my kids, both at home and with yours, at school!', public.ces_uuid('assets', 'IMG_3066.JPG'), true, 31, '{"blueprint":"people","classrooms":["448d749d-93d0-4c81-bd6f-806e5e431849"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:52:39.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '328dac6a-39bb-4cfe-bfca-9d8b36a34b5c'), '328dac6a-39bb-4cfe-bfca-9d8b36a34b5c', 'jeanette-herrera', 'Jeanette Herrera', 'Spanish Room Head Teacher', '2018-01-01'::date, 'Jeanette@Cambridge-Ellis.org', 'I grew up in Lima, Peru, and am fluent in Spanish and Portuguese. Since moving to the US over a decade ago, I have had the pleasure of working with infants and children of all ages as a nanny. Through these experiences, I realized I wanted to become a teacher. In 2019, I completed my Associate’s Degree in Early Childhood Education. In 2022, I finished my Bachelor of Arts in Early Childhood Education and Care at Cambridge College. I love to travel with my family, and my favorite food is ceviche.', public.ces_uuid('assets', 'jeanette-headshot.png'), true, 32, '{"blueprint":"people","classrooms":["9f3c379b-1411-420e-a43b-8370437954d0"],"programs":["language"],"template":"bio"}'::jsonb, '2025-02-11T19:50:09.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '55c6d51a-07ca-41c5-b091-a98abc416aa0'), '55c6d51a-07ca-41c5-b091-a98abc416aa0', 'jermaine-cook-wright', 'Jermaine Cook-Wright', 'Blue Room Teacher; Faculty Board Representative', '2000-02-01'::date, 'Jermaine@Cambridge-Ellis.org', 'I am originally from Jamaica. As a child, I always wanted to be in the military, but after a summer of helping a friend who owned a preschool, I found my true calling. I became a preschool teacher in Jamaica in 1997, then moved to the US before the birth of my first daughter. I joined the teaching team at Cambridge-Ellis in 1999. I love being a preschool teacher, and I truly think it’s the best job in the world. I have been married for over two decades, and I have 3 children who have all gone to Cambridge-Ellis.', public.ces_uuid('assets', 'jermaine-headshot.jpg'), true, 33, '{"blueprint":"people","classrooms":["af22aa7b-08f2-4f3a-b509-10c03031eee4"],"programs":["day"],"template":"bio"}'::jsonb, '2025-07-23T17:09:54.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '1fd40086-9bbb-4eea-8a66-77c2bfa4acf1'), '1fd40086-9bbb-4eea-8a66-77c2bfa4acf1', 'jessica-tangren', 'Jessica Tangren', 'Board Clerk', null, 'jessica.tangren@gmail.com', null, public.ces_uuid('assets', 'jessica-tangren-headshot.JPG'), true, 34, '{"blueprint":"people"}'::jsonb, '2025-07-23T16:52:29.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'b17491fb-44b0-47a7-a8ca-173b1fd71eaa'), 'b17491fb-44b0-47a7-a8ca-173b1fd71eaa', 'joel-renfort', 'Joel Renfort', 'French Teacher', null, 'Joel@Cambridge-Ellis.org', E'Working with children has always been a part of my world and my family experience. As a budding artist, I worked with my family to enrich the classrooms of the students in their care, as my parents were educators as well. I continued in this domain, basing my Master''s thesis on Language Development and Usage at the preschool level before returning to work in school leadership and pedagogy for 16 years in the preschool setting. \n\nIn my free time, I like to spend time with family and friends, read, create art, write poetry, visit museums, play chess, and learn about other cultures. I truly believe that working with children invites you to become more aware, motivated, energetic, creative, and innovative. The exchanges with children, colleagues, families, and caregivers contribute to an atmosphere focused on giving. As I wrote in one of my poems, "there is no better business than giving."', public.ces_uuid('assets', 'joel-renfort.JPG'), false, 35, '{"blueprint":"people"}'::jsonb, '2024-08-03T21:44:29.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'd2edb398-828c-4f5a-adbd-a89657ee8617'), 'd2edb398-828c-4f5a-adbd-a89657ee8617', 'justine-waddell', 'Justine Bathurst', 'Floating Teacher', '2024-08-23'::date, 'Justine@Cambridge-Ellis.org', E'I grew up on the beautiful island of Nantucket, where I spent all of high school and many summers home from college nannying, teaching dance lessons, and substitute teaching, which\ninstilled in me a passion for working with young children. After completing a BA in International Relations and living in Spain for three years, I worked as an EMT in Boston, specializing in\nNICU transport. Knowing that I ultimately wanted to return to working with children, I then became a full-time nanny, during which time I was able to be deeply involved in child growth\nand development. In my free time, I love to volunteer, spend time outside, and explore the city with friends. I am so excited to continue growing alongside the teachers, families, and children\nat CES.', public.ces_uuid('assets', 'justine-waddell.jpeg'), false, 36, '{"blueprint":"people"}'::jsonb, '2025-07-23T18:00:50.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'ab22daab-a42d-4ca8-b1bc-448af0e5445f'), 'ab22daab-a42d-4ca8-b1bc-448af0e5445f', 'kaitlyn-kelley', 'Kaitlyn Kelley', 'Board Member', null, 'mamakaitlynelizabeth@gmail.com', null, public.ces_uuid('assets', 'kaitlyn-kelley-headshot-1742218602.JPG'), false, 37, '{"blueprint":"people"}'::jsonb, '2025-07-23T16:53:53.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '216940bc-4a00-404a-9af6-77f10bc771c5'), '216940bc-4a00-404a-9af6-77f10bc771c5', 'karla-cano', 'Karla Cano', 'Spanish Teacher', null, 'Karla@Cambridge-Ellis.org', 'I was born and raised in Mexico. My native language is Spanish. I am passionate about teaching, learning, reading, and listening to music. I earned my bachelor''s degree in education in Mexico. I started teaching in 2012 in a multi-age group and got my license as a public education teacher in 2016. After two years as a teacher in public schools in Mexico, I decided to come to this country to learn English. Cambridge-Ellis School opened its doors to me as a volunteer Spanish teacher in 2022 and since then I fell in love and now I decided to start my new adventure here.', public.ces_uuid('assets', 'karla-cano-headshot.jpg'), false, 38, '{"blueprint":"people"}'::jsonb, '2024-08-02T18:03:53.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'b62f667c-6790-4e04-a4d4-0c1eb26fd8cf'), 'b62f667c-6790-4e04-a4d4-0c1eb26fd8cf', 'kate-faust', 'Kate Faust', 'Strategic Planning Committee Chair; Community Builders Committee Co-Chair', null, 'katetaylor9@gmail.com', null, public.ces_uuid('assets', 'kate-taylor-faust-headshot.JPG'), true, 39, '{"blueprint":"people"}'::jsonb, '2025-07-23T16:54:45.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '75862a02-1182-48da-aeed-14e0714e846d'), '75862a02-1182-48da-aeed-14e0714e846d', 'katie-clark', 'Katie Clark', 'Arts Coordinator', '2010-09-07'::date, 'Katie@Cambridge-Ellis.org', 'I have been working in the field of early education since 1984 as a teacher, director, and literacy-based creative movement specialist. Since 2009, I have been the Arts Coordinator at Cambridge-Ellis School and am now integrating all of my experiences to design, teach, and oversee a creative and enriching arts program for children ages two to five years. My work is well suited to my lifestyle as I enjoy visiting museums, listening to music, attending dance performances, and staying current on the latest children’s picture books.', public.ces_uuid('assets', 'IMG-8342-2.jpg'), true, 40, '{"blueprint":"people","template":"bio"}'::jsonb, '2025-09-09T21:16:51.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '85447551-542f-4f4d-b377-d908f98c822a'), '85447551-542f-4f4d-b377-d908f98c822a', 'kim-rogers', 'Kim Rogers', 'Director of Development', null, 'Kim@Cambridge-Ellis.org', 'With over 19 years of philanthropic management experience in the non-profit education space in Manhattan, I joined the Cambridge-Ellis School in 2016. Previously, I worked as a senior major gifts specialist and volunteer management director at Columbia University and PBS Channel Thirteen. I enjoy connecting with parents and alumni to enrich the lives of our earliest learners on behalf of the Cambridge-Ellis School. From Provincetown, Massachusetts, I currently reside in Cambridge with my husband and son.', public.ces_uuid('assets', 'Kim Rogers.jpg'), false, 41, '{"blueprint":"people","template":"bio"}'::jsonb, '2021-10-25T15:27:37.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '3e78b585-dab9-4146-a11f-68eefd1c9303'), '3e78b585-dab9-4146-a11f-68eefd1c9303', 'laura-colarusso', 'Laura Colarusso', 'Clerk', null, null, null, null, false, 42, '{"blueprint":"people"}'::jsonb, '2023-07-12T16:19:07.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'db36433f-8439-45d3-9081-38ee0d9bef74'), 'db36433f-8439-45d3-9081-38ee0d9bef74', 'laura-kelly', 'Laura Kelly', 'Green Room Co-Head Teacher', '2017-09-01'::date, 'Laura@Cambridge-Ellis.org', 'After graduating from college and working briefly as a journalist, I rediscovered my passion for working with young children while volunteering at a preschool for children who were homeless. I have taught ages 3-5 and have been teaching at CES since 2017. My favorite part about teaching is seeing the world through the children’s eyes and learning beside them. In my spare time, I enjoy traveling, exploring new places, and relaxing at my family’s lake house in NH.', public.ces_uuid('assets', 'laura-headshot.png'), true, 43, '{"blueprint":"people","classrooms":["9ae28b20-3a65-4e4b-8f56-4de6eef458f9"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:54:33.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '6099fb98-b07d-4e5c-907f-0a1e517d2d0f'), '6099fb98-b07d-4e5c-907f-0a1e517d2d0f', 'leguan-xie', 'Leguan Xie', 'Mandarin Jade Head Teacher', '2025-08-25'::date, 'Leguan@Cambridge-Ellis.org', 'I am excited to join to CES community as the Mandarin Jade Room teacher for school-age children! Born and raised in China, I came to the United States in 2015 and soon discovered my passion for education through tutoring. Since then, I have pursued teaching with dedication and joy. I hope to share Mandarin language and culture with children in a way that feels authentic and engaging. My goal is to help children not only gain language skills but also develop an appreciation for cultural diversity. I am thrilled to be part of a community that values learning, curiosity, and connection.', public.ces_uuid('assets', '2025-26-leguan-head-shot.jpg'), true, 44, '{"blueprint":"people"}'::jsonb, '2025-09-09T20:43:40.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '26b39d59-4809-47b7-9f13-650c6fc30bd5'), '26b39d59-4809-47b7-9f13-650c6fc30bd5', 'lily-carey', 'Lily Carey', 'Red Room Co-Head Teacher and Summer Program Coordinator', '2019-08-23'::date, 'Lily@Cambridge-Ellis.org', 'This is my sixth year at Cambridge Ellis but I’ve worked for over a decade as a toddler teacher. I am constantly amazed by how much your wonderful toddlers teach me through their curiosity, creativity, and growth. I come from a creative arts background and love sharing that with the class. In my free time, I enjoy spending time with my husband and daughter, a current CES student.', public.ces_uuid('assets', 'lily-headshot.png'), true, 45, '{"blueprint":"people","classrooms":["448d749d-93d0-4c81-bd6f-806e5e431849"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:55:03.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'c1da77d0-719a-4bc9-8d93-dc8136490a5d'), 'c1da77d0-719a-4bc9-8d93-dc8136490a5d', 'lindsey-freedman', 'Lindsey Freedman', 'Director of Education', null, 'Lindsey@Cambridge-Ellis.org', E'I earned my BA in Anthropology from Brandeis University then my M.S. Ed. in Early Childhood General and Special Education from Bank Street College of Education in 2007. I have been teaching preschool for almost 20 years, most recently at The Little School in San Francisco, a full inclusion school that focuses on social and emotional development.\n\nI grew up in Brookline and Cambridge. My grandmother’s joyful guidance, genuine interest in my ideas, and contagious passion for learning continues to inspire my work with children, parents, and teachers. \n\nI spend my free time with my own adventurous preschooler, Gus. We love to splash in the waves at Nantasket beach, meander through the Arnold Arboretum, and read stacks of books.', public.ces_uuid('assets', 'lindsey.jpg'), true, 46, '{"blueprint":"people"}'::jsonb, '2025-09-09T21:15:08.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '3c7a9eb5-fd7a-4dc0-b150-93868993baa1'), '3c7a9eb5-fd7a-4dc0-b150-93868993baa1', 'liz-mckillop-segura', 'Liz McKillop-Segura', 'Blue Room Co-Head Teacher', '2019-08-23'::date, 'Elizabeth@Cambridge-Ellis.org', 'I am an experienced early childhood educator and hold a degree in Health and Human Services, with a major in Child and Family Studies. For the past 8 years I served as director of an Early Childhood Program and prior to that also taught for 8 years. I am excited about joining the Blue Room and continuing arts integration in play-based teaching at CES!', public.ces_uuid('assets', 'Liz McKillop-Segura.jpg'), true, 47, '{"blueprint":"people","classrooms":["af22aa7b-08f2-4f3a-b509-10c03031eee4"],"programs":["day"],"template":"bio"}'::jsonb, '2025-09-09T20:40:10.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '53c49a4d-7fd4-4ad9-99a2-2659a9283bc6'), '53c49a4d-7fd4-4ad9-99a2-2659a9283bc6', 'liz-tedesco', 'Liz Tedesco', 'Blue Room Co-Head Teacher', '2012-09-01'::date, 'Liz@Cambridge-Ellis.org', 'After graduating from college, I began my career in the early childhood field by spending two years working as an AmeriCorps volunteer in the Addison County Child Care Services Office in Vermont. Since then, I have happily spent the last twenty plus years teaching in toddler and preschool classrooms in Vermont, Colorado, and Massachusetts. I began teaching at CES in 2012, and I feel very fortunate to be working with the children and families we serve in our incredible community. In my spare time, I love to read, spend time outside, and go on adventures both near and far (especially to Argentina where I lived for two years).', public.ces_uuid('assets', 'liz-t-headshot.jpg'), true, 48, '{"blueprint":"people","classrooms":["af22aa7b-08f2-4f3a-b509-10c03031eee4"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:55:50.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '28d307a1-5066-4d82-bbe0-7e5787034d0b'), '28d307a1-5066-4d82-bbe0-7e5787034d0b', 'liz-vance', 'Liz Vance', 'Co-Head Teacher', '2024-08-23'::date, 'Lizv@Cambridge-Ellis.org', E'I began my career as a preschool teacher in a parent cooperative, right here in\nCambridge. After 6 years in the classroom, I founded Muckykids Art Studio, a\nprocess-based art studio for young children. After many wonderful years at\nMuckykids, I decided to ‘retire’ from owning a business, and I am so excited to get\nback to my preschool roots & join the CES community. In the Yellow Room, I’m\nlooking forward to spending our days immersed with the kids in our hands-on\ncurriculum, full of nature, art, books, and play! I live in Cambridge with my husband\nand our two children, Max and Grace. In my free time, I enjoy crafting, walking,\ntaking long bike rides, and reading.', public.ces_uuid('assets', 'liz-vance-headshot.jpg'), true, 49, '{"blueprint":"people"}'::jsonb, '2025-07-23T17:57:24.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'e0a9289c-a6ee-4e10-9270-aa2d3fef591c'), 'e0a9289c-a6ee-4e10-9270-aa2d3fef591c', 'maraliz-ramos', 'Maraliz Ramos', 'Spanish Co-Head Teacher', '2025-08-22'::date, 'Maraliz@Cambridge-Ellis.org', 'I am originally from Puerto Rico and have six years of experience working with children of various ages. My native language is Spanish. I hold a Bachelor''s degree from Antillean Adventist University in Elementary Education (K-5) with a focus on Spanish, mathematics, science, and social studies. I moved to Massachusetts with the goal of personal and professional growth. In my free time, I enjoy painting, exercising, and being in nature.', public.ces_uuid('assets', '2025-26-maraliz-head-shot.jpg'), true, 50, '{"blueprint":"people"}'::jsonb, '2025-09-09T20:20:24.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '9b517d7d-3b1c-432e-b9f9-700da7d5eb6b'), '9b517d7d-3b1c-432e-b9f9-700da7d5eb6b', 'mary-anne-santos', 'Mary Anne Santos', 'Purple Room Head Teacher', '2009-09-08'::date, 'MaryAnne@Cambridge-Ellis.org', 'After a brief career as a graphic designer, I returned to school to live out my dream as a Reggio-inspired educator of young children. I’m passionate about fostering relationships in the CES community and creating warm, nurturing environments for the children to explore and connect with each day. I love working with preschool children as they make connections and share their perspectives. Outside of work, I enjoy traveling with my husband and daughter, as well as spending time on the beaches of New England and beyond.', public.ces_uuid('assets', 'Mary Anne Santos.jpg'), true, 51, '{"blueprint":"people","classrooms":["7c58e147-8daa-4bf1-9ef4-0c2d74ac028f"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:57:31.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'b5bb8cd0-648d-4365-b5ed-6d82d8c1a81c'), 'b5bb8cd0-648d-4365-b5ed-6d82d8c1a81c', 'mary-dutczak', 'Mary Dutczak', 'Mandarin Room Co-Head Teacher', '2021-10-13'::date, 'Mary@Cambridge-Ellis.org', 'I have a BA in Chinese Language and Literature from Umass Amherst. In 2014, I began my journey in early childhood education as a temporary teacher but immediately fell in love with the work. Since then, I have continued my education to gain the knowledge and skills to provide young children with a warm and rich school experience. I joined Cambridge-Ellis in 2021, first as parental leave coverage in the Day Program before finding a home in the Mandarin Language Program. Outside of school, I like to travel and explore new places.', public.ces_uuid('assets', 'mary-dutczak-headshot.jpg'), true, 52, '{"blueprint":"people","programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:57:09.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'e2a0afb3-a63a-45a1-b534-2b52fc413bd2'), 'e2a0afb3-a63a-45a1-b534-2b52fc413bd2', 'maura-walsh', 'Maura Walsh', 'Amber Room Co-Head Teacher', '2009-09-08'::date, 'Maura@Cambridge-Ellis.org', 'I joined Cambridge-Ellis in 2009. I love working with wide age groups in which children can explore together, develop relationships, and learn from each other. I can’t wait to dive into our year-long child-directed inquiry this year and see where the children’s interests will take us! I also enjoy presenting at Early Childhood Education conferences, sharing our practices with other educators, particularly on curriculum development, nature education, and DEI work with young children. I live in Dedham with my husband, Tom, and children, Finn and Bonnie, both CES alums. In my free time, I love reading, knitting, hiking, and engaging in social justice work.', public.ces_uuid('assets', 'maura-headshot.jpg'), true, 53, '{"blueprint":"people","classrooms":["eb19cc0e-2314-4252-8f6c-af927cfa0ab2"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T19:58:08.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'ec4dc537-40cc-432f-b7fe-d4037bbce162'), 'ec4dc537-40cc-432f-b7fe-d4037bbce162', 'maya-bonanno', 'Maya Bonanno', 'Rainbow Room Teacher', '2025-08-22'::date, 'MayaB@Cambridge-Ellis.org', 'I’m originally from New Jersey, and I recently moved to Boston full-time. I attended Simmons University for my undergraduate studies and majored in Social Work. I have always felt passionate about serving and supporting other people. I have always loved children and plan to become a school social worker one day. I enjoy walking, cooking, and shopping in my free time. I can not wait to meet all your children and have a great school year!', public.ces_uuid('assets', '2025-26-maya-b.-head-shot.jpg'), true, 54, '{"blueprint":"people"}'::jsonb, '2025-09-09T20:34:18.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'ba5e2e4c-de54-4db5-ad38-4fa3e305efd6'), 'ba5e2e4c-de54-4db5-ad38-4fa3e305efd6', 'michelle-huang', 'Michelle Huang', 'Treasurer and Finance Committee', null, 'msh1018@gmail.com', null, public.ces_uuid('assets', 'michelle-huang-headshot.JPG'), true, 55, '{"blueprint":"people"}'::jsonb, '2025-07-23T16:55:47.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '33a7ddbf-7537-404a-8dd7-ce4b3a4b4f47'), '33a7ddbf-7537-404a-8dd7-ce4b3a4b4f47', 'michelle-phoenix', 'Michelle Phoenix', 'Office Manager', '2021-06-21'::date, 'Michelle@Cambridge-Ellis.org', 'I''ve spent all of my working life in client facing services. I''ve been a clerk at a record store, a unit coordinator on a surgical ward, a spa owner and operator, and an admin of various stripes. I get a lot of pleasure and satisfaction from helping people, be it problem solving, gathering resources, putting people at ease, or just being a friendly ear. My interests lie in racial justice, LGBTQIA+ advocacy, science & technology, nail art, nature photography, and live music. I''m really pleased to be part of the leadership team at Cambridge-Ellis and look forward to many years of service to the community.', public.ces_uuid('assets', 'mp-headshot.JPG'), true, 56, '{"blueprint":"people","template":"bio"}'::jsonb, '2025-02-11T16:29:56.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'f54515d7-328e-4abf-8548-3c133ca48529'), 'f54515d7-328e-4abf-8548-3c133ca48529', 'molly-cohen', 'Molly Cohen', 'Development Committee Chair', null, 'molly.s.cohen@gmail.com', null, public.ces_uuid('assets', 'molly-cohen-headshot.png'), true, 57, '{"blueprint":"people"}'::jsonb, '2025-07-23T16:56:23.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'ea30215b-0147-4ca1-9bff-65b7c041b0d5'), 'ea30215b-0147-4ca1-9bff-65b7c041b0d5', 'molly-howard', 'Molly Howard', 'Board Member', null, 'molly.e.howard@gmail.com', null, public.ces_uuid('assets', 'molly-howard-headshot.JPG'), false, 58, '{"blueprint":"people"}'::jsonb, '2024-09-23T16:29:04.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '303b5eab-1970-4da9-84ae-9782c7b58fee'), '303b5eab-1970-4da9-84ae-9782c7b58fee', 'nancy-goldberg', 'Nancy Goldberg', 'Floating Teacher', null, 'Nancy@Cambridge-Ellis.org', 'I am a mostly-retired teacher and graphic designer. My interests have led me to 25+ years teaching, including a stint at CES, and a design path that has included working at WGBH, the Boston Globe and other publications. I’m so lucky to be able to continue spending time with the children and community at CES. For me, there is nothing more joyous than being part of a child’s discovery of the world.', public.ces_uuid('assets', 'nancy-headshot.jpeg'), true, 59, '{"blueprint":"people"}'::jsonb, '2024-09-05T13:43:45.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'c57e4fb9-2ffe-403f-9a2f-ea5b62d48ce3'), 'c57e4fb9-2ffe-403f-9a2f-ea5b62d48ce3', 'natasha-carr', 'Natasha Carr', 'Orange Room Co-Head Teacher', '2021-06-21'::date, 'Natasha@Cambridge-Ellis.org', 'I am proud to be a toddler mom and teacher! Cambridge-Ellis is where my love for childhood education sparked. I began volunteering at 16 years old and have been part of the community since! My experience has allowed me to work closely with children from ages 0-6, in and out of the classroom. In 2019, I earned a BA from UMASS Boston, with a degree in early education with a concentration in inclusive settings. Outside of school, I enjoy nature, art and spending time with loved ones!', public.ces_uuid('assets', 'Natasha Dimas.jpg'), true, 60, '{"blueprint":"people","classrooms":["a289ada5-75ed-4478-a0ac-457b827c8850"],"programs":["language"],"template":"bio"}'::jsonb, '2025-07-23T17:10:58.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '24a03bef-6647-4438-9ca9-b53f664b51ea'), '24a03bef-6647-4438-9ca9-b53f664b51ea', 'nathalie-roberts', 'Nathalie Roberts', 'Board Member', null, 'nathalieroberts10@gmail.com', null, public.ces_uuid('assets', 'nathalie-roberts-headshot.JPG'), false, 61, '{"blueprint":"people"}'::jsonb, '2024-09-23T16:30:43.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'ec6d455d-6bbd-4bfd-8c42-384ef7eff45e'), 'ec6d455d-6bbd-4bfd-8c42-384ef7eff45e', 'neil-tennenholtz', 'Neil Tenenholtz', 'Board Member', null, 'neil.tenenholtz@gmail.com', null, public.ces_uuid('assets', 'neil-tenenholtz-headshot.JPG'), true, 62, '{"blueprint":"people"}'::jsonb, '2024-10-29T14:56:50.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'c5ead9da-5be7-477d-b882-1cbdaa1f3f0b'), 'c5ead9da-5be7-477d-b882-1cbdaa1f3f0b', 'nisha-deo', 'Nisha Deo', 'Diversity, Equity, & Inclusion (DEI) Committee Co-Chair', null, 'nish2o@gmail.com', null, null, false, 63, '{"blueprint":"people"}'::jsonb, '2024-09-23T16:32:27.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'd75cb51c-d24c-4c43-84a2-7ec8feb995f6'), 'd75cb51c-d24c-4c43-84a2-7ec8feb995f6', 'petra-loney', 'Petra Loney', 'Floating Teacher', '2022-01-03'::date, 'Petra@Cambridge-Ellis.org', 'I have been working with young children for over 30 years! I attended Bunker Hill Community College, where I received my Infant, Toddler, and Preschool Teacher certification. I usually work as a floating teacher and often serve as long-term coverage for teachers on family leave. My passion is working with young children and teaching them the social-emotional skills needed to prepare them for future learning. Growing up, I came from a large family. I am the third oldest of nine siblings. I loved caring for my younger siblings. It prepared me for motherhood, where I raised two boys, and eventually grew into my love of teaching children. My hobbies include taking long walks, dancing, and spending time with my family and friends.', public.ces_uuid('assets', '526138ff-778e-4e0e-a3fd-d1f5e7491961.jpeg'), true, 64, '{"blueprint":"people"}'::jsonb, '2025-02-11T19:59:44.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'd55c3300-37a9-45f6-9ad6-f6adee381cc2'), 'd55c3300-37a9-45f6-9ad6-f6adee381cc2', 'qiaoling-zheng', 'Qiaoling Zheng', 'Mandarin Room Co-Head Teacher, Red Room Teacher', '1998-10-01'::date, 'Qiaoling@Cambridge-Ellis.org', 'I have been teaching at Cambridge Ellis School since 1998. Currently, I work both as a teacher in the Red Room and co-head teacher in the Mandarin Blue Room. After 26 years of teaching, I believe that the role of "teacher-friend" is the way to build a two-way, trusting relationship with my students, where they feel comfortable with me and approach me with all kinds of their needs. I have shared my Chinese culture with children across the school to foster a sense of appreciation and curiosity.', public.ces_uuid('assets', 'qiaoling-headshot.png'), true, 65, '{"blueprint":"people","classrooms":["448d749d-93d0-4c81-bd6f-806e5e431849","1bdc622f-5bcd-4d93-ab82-89cac9bc1b49"],"programs":["day","language"],"template":"bio"}'::jsonb, '2025-02-11T20:00:26.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'c9517f69-24af-4d2c-b524-2133e2ed9aa7'), 'c9517f69-24af-4d2c-b524-2133e2ed9aa7', 'qiurong-chen', 'Qiurong Chen', 'Mandarin Room Co-Head Teacher', '2024-08-23'::date, 'Qiurong@Cambridge-Ellis.org', E'I was born and raised in China and moved to the United States in 2023. My native\nlanguages are Mandarin and Cantonese. I love learning languages and hope to share\nthis passion with my students as they learn Mandarin. After graduating in 2019, I\nworked as an elementary school teacher in China. I truly enjoy spending time with\nchildren and helping them discover their potential. I&#39;m excited to join the CES family\nand look forward to creating a fun and engaging learning environment for our\nstudents.', public.ces_uuid('assets', 'qiurong.jpg'), true, 66, '{"blueprint":"people"}'::jsonb, '2025-07-23T18:02:04.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'bef2a16f-4191-4bfb-b85b-f2016280ca91'), 'bef2a16f-4191-4bfb-b85b-f2016280ca91', 'rahul-khara', 'Rahul Khara', 'Board Co-Chair', null, 'rahul.khara@gmail.com', null, public.ces_uuid('assets', 'rahul-khara-headshot.JPG'), true, 67, '{"blueprint":"people"}'::jsonb, '2025-07-15T15:05:32.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'fc16d5a5-8bdc-49e1-be6d-edfc8c83a9dc'), 'fc16d5a5-8bdc-49e1-be6d-edfc8c83a9dc', 'rina-gandhi', 'Rina Gandhi', 'Board Member', null, 'rina.b.gandhi@hotmail.com', null, public.ces_uuid('assets', 'rina-gandhi-1758203238.jpg'), true, 68, '{"blueprint":"people"}'::jsonb, '2025-09-18T13:47:27.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'da9b7489-43e6-42f9-837e-d46dfa84983a'), 'da9b7489-43e6-42f9-837e-d46dfa84983a', 'sara-angres', 'Sara Angres', 'Purple Room Co-Head Teacher', '2025-08-22'::date, 'Sara@Cambridge-Ellis.org', 'I have been finding joy in the field of early childhood education for over twenty-five years. For the majority of my teaching career, I have taught pre-kindergarten and kindergarten-aged children. In 2012, I had the opportunity to visit the schools of Reggio Emilia, Italy, with a study group. This experience has profoundly shaped my perspective and approach to both education and parenting. I am thrilled to join CES and the community of learners that truly honors and values children in such meaningful ways.  Outside of teaching, I enjoy traveling, spending time with family & friends, and listening to live music, especially when my son is behind the drums!', public.ces_uuid('assets', '2025-26-sara-head-shot.jpg'), true, 69, '{"blueprint":"people"}'::jsonb, '2025-09-09T20:36:43.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'd44d47e6-dae6-4451-b9d5-4a6fe87c9400'), 'd44d47e6-dae6-4451-b9d5-4a6fe87c9400', 'shantia-gary', 'Shantia Gary', 'Diversity Equity & Inclusion Committee', null, 'tiag316@gmail.com', null, public.ces_uuid('assets', 'shantia-gary.jpg'), true, 70, '{"blueprint":"people"}'::jsonb, '2025-09-18T13:50:44.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'cfa1f635-908f-4d30-9812-cfe881bcddc7'), 'cfa1f635-908f-4d30-9812-cfe881bcddc7', 'trevor-freeman', 'Trevor Freeman', 'Floating Teacher', '2024-08-23'::date, 'Trevor@Cambridge-Ellis.org', 'I began my journey teaching in Applied Behavioral Analysis working with special education students with autism. I fell in love with the teaching aspect of ABA after spending time in a classroom. I slowly moved into being a special education paraprofessional. Now, I aspire to lead a classroom after the completion of my master’s in education. I hope to be able to apply what I have learned as an ABA and a paraprofessional in any and every classroom I have the opportunity to teach. When I am not teaching, you can find me cheerleading. I am committed to two competitive all-star cheerleading teams in the North Shore that I get to travel and perform with all year.', public.ces_uuid('assets', 'trevor-headshot.jpg'), true, 71, '{"blueprint":"people"}'::jsonb, '2025-07-23T18:00:22.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'b336b28f-cd15-4cb8-92b9-d5422addeb44'), 'b336b28f-cd15-4cb8-92b9-d5422addeb44', 'tullah-dash', 'Tullah Dash', 'Yellow Room Co-Head Teacher', null, 'Tullah@Cambridge-Ellis.org', 'I have worked in education for over ten years, and this will be my seventh year working in early childhood. I studied anti-bias education and progressive pedagogy while earning my Master’s Degree at Hunter College in New York City. When working with toddlers I enjoy providing ample opportunity for exploring open-ended materials and the natural environment, as well as giving much time and energy to nurturing the children’s social emotional development and communication skills. Outside of school I am a mother to a three year old, a writer, and a dancer. I enjoy going on bike rides with my family, writing and illustrating children’s books, and being involved in social justice work.', public.ces_uuid('assets', '83fbb7b2-268a-44fe-abb2-f9498698a179.jpeg'), false, 72, '{"blueprint":"people","classrooms":["73f44629-52d8-444e-8cc4-35a3a7569479"],"programs":["day"],"template":"bio"}'::jsonb, '2023-07-12T16:22:07.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '8cd47516-62bd-4fac-98bb-5ee4df634967'), '8cd47516-62bd-4fac-98bb-5ee4df634967', 'ursula-arruda', 'Ursula Arruda', 'Yellow Co-Head Teacher', '2023-08-21'::date, 'Ursula@Cambridge-Ellis.org', 'I am a lifelong resident of Cambridge and have been teaching for over twenty years! I enjoy helping each child progress in all areas of their development– academic, social, language, and motor. I strive to create a community of learners that nurtures this growth in a positive and fun environment. Personally, I have two grown children, ages 24 and 28. I love to travel. Give me the ocean and a beach any day! I enjoy baking, music, and spending time with family and friends. I look forward to working together with you as partners in your child’s growth and development!', public.ces_uuid('assets', 'ursula-headshot.jpg'), true, 73, '{"blueprint":"people"}'::jsonb, '2025-02-11T20:01:31.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'db9ed644-ea57-461f-bbdd-1eb82e53a8ce'), 'db9ed644-ea57-461f-bbdd-1eb82e53a8ce', 'vilmari-gonzalez', 'Vilmari Gonzalez', 'Yellow Room Co-Head Teacher', null, 'Vilmari@Cambridge-Ellis.org', 'I was born and raised in Cambridge, MA and am a native Spanish speaker. I earned my Bachelor’s degree from Bennington College and thus began my journey into Education. I have been working in early childhood education for eight years and I am excited to dive into my fourth year at CES! My goal is to instill confidence and inspire a lifelong love of learning. I myself enjoy learning new skills and activities! In my free time I enjoy dancing, ice skating, archery, and reading.', public.ces_uuid('assets', 'vilmari-headshot.jpg'), false, 74, '{"blueprint":"people","classrooms":["9f3c379b-1411-420e-a43b-8370437954d0"],"programs":["language"],"template":"bio"}'::jsonb, '2024-08-03T22:40:06.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '56014be6-3e8c-4ff6-b500-039549190c03'), '56014be6-3e8c-4ff6-b500-039549190c03', 'wendy-henderson', 'Wendy Henderson', 'Orange Room Teacher', '2016-01-01'::date, 'Wendy@Cambridge-Ellis.org', 'I was born and raised in Miami, and I am a native Spanish speaker. I have been living in Cambridge for over two decades and currently reside with my husband, two alumni CES children, and my dog Archie. My inspiration and love for children began after having my own. I joined the CES staff to earn my early childhood teaching license and am very excited to return to the Orange Room. I enjoy running, skiing, biking, traveling, and spending time with family and friends.', public.ces_uuid('assets', 'wendy-headshot.png'), true, 75, '{"blueprint":"people","classrooms":["8f6909ad-b9a1-41e8-b54e-b0f90bfc48ba"],"programs":["day"],"template":"bio"}'::jsonb, '2025-02-11T20:02:14.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', 'a2b61a23-cc9e-4ba3-ac3f-1b65b1025223'), 'a2b61a23-cc9e-4ba3-ac3f-1b65b1025223', 'yiting-wu', 'Yiting Wu', 'Mandarin Room Co-Head Teacher', null, 'Yiting@Cambridge-Ellis.org', 'I am thrilled to be Chinese teacher this year. I completed my master''s degree in early childhood education in Umass Amherst. I have several years of teaching experience in preschool and kindergarten. My goal as the teacher is to make children learn with fun and have more experiences in class. I look forward to learning and growing with all of you!', public.ces_uuid('assets', 'f83a9f04-af1b-42d4-b39d-b0f2e0caf6f0.jpeg'), false, 76, '{"blueprint":"people","classrooms":["1bdc622f-5bcd-4d93-ab82-89cac9bc1b49"],"programs":["language"],"template":"bio"}'::jsonb, '2022-09-13T21:06:37.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('people', '89f3addc-2951-465b-a6cb-4f3eec76d72b'), '89f3addc-2951-465b-a6cb-4f3eec76d72b', 'yu-shiuan-carol-shie', 'Carol Shie', 'Mandarin Room Co-Head Teacher', '2024-08-23'::date, 'Carol@Cambridge-Ellis.org', 'I recently earned my Master’s in Early Childhood Education from Lesley University after being a licensed teacher and working in multiple schools for several years in Taiwan. I enjoy guiding children to discover their potential and become more confident individuals. It is important for me to listen to each child so they feel loved and understood. In my free time, I enjoy dancing and exploring new places and cuisines. This is my first year at CES, and I am very excited to be part of the family.', public.ces_uuid('assets', 'yu-shiuan-carol-shie.jpeg'), true, 77, '{"blueprint":"people"}'::jsonb, '2025-07-23T18:02:22.000Z', 'bekah@cambridge-ellis.org')
