insert into public.classrooms
  (id, legacy_ref, slug, title, description, age_range, published, sort_order, legacy, source_updated_at, source_updated_by)
values
  (public.ces_uuid('classrooms', 'eb19cc0e-2314-4252-8f6c-af927cfa0ab2'), 'eb19cc0e-2314-4252-8f6c-af927cfa0ab2', 'amber-room', 'Amber Room', 'Depending on the needs of the school, the Amber Room may span Lower and/or Upper Preschool. We use the Inquiry Approach to develop year-long studies based on the children’s interests as they explore the world around them through play and first-hand experiences. Past year-long Inquiries have been in Music, Pets, Construction, Food Preparation, Textiles, and Simple Machines, to name just a few!', null, true, 1, '{"ages":"upper-preschool","blueprint":"classrooms","programs":"day","teachers":["e2a0afb3-a63a-45a1-b534-2b52fc413bd2","3bb1c2b6-2776-4b43-a958-9dd30c3ceea3"]}'::jsonb, '2024-09-27T17:35:02.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', 'af22aa7b-08f2-4f3a-b509-10c03031eee4'), 'af22aa7b-08f2-4f3a-b509-10c03031eee4', 'blue-room', 'Blue Room', 'The Blue Room is for Upper Preschool children. Classroom curriculum is emergent—based on the interests of the children and encompasses all learning areas including literacy, math, sensory, science, block play, art, dramatic play, and physical movement. The Blue Room focuses on whole child development and supports children’s social/emotional, cognitive, and physical development as they gain important school readiness skills through play-based, experiential learning.', null, true, 2, '{"ages":"upper-preschool","blueprint":"classrooms","programs":"day","teachers":["53c49a4d-7fd4-4ad9-99a2-2659a9283bc6","3c7a9eb5-fd7a-4dc0-b150-93868993baa1","55c6d51a-07ca-41c5-b091-a98abc416aa0"]}'::jsonb, '2025-09-09T21:04:02.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', 'a446e4db-e4cc-4662-8a14-9b647d6ba7c2'), 'a446e4db-e4cc-4662-8a14-9b647d6ba7c2', 'french-room', 'French Yellow', 'The French Room welcomes children ranging from 2.9 to 6 years old. Through immersion in the French language, and an emergent and play-based curriculum with a focus on the arts and outdoor exploration, we are able to accommodate students at all levels of French learning, and individually challenge them based on where they are in their language development. We expose children to the different traditions of each of the French-speaking cultures of the world through the exploration of food, dance, celebrations, and music.', null, true, 3, '{"ages":"preschool","blueprint":"classrooms","programs":"language","teachers":["fb148191-0943-43e6-912c-a201bad7dae8","e8ac136c-ebf2-485a-9240-f3233bad51e7"]}'::jsonb, '2026-01-12T20:27:46.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', '9ae28b20-3a65-4e4b-8f56-4de6eef458f9'), '9ae28b20-3a65-4e4b-8f56-4de6eef458f9', 'green-room', 'Green Room', 'The Green Room is for Lower Preschool children. Our emergent classroom curriculum is strongly influenced by the Reggio Emilia approach to early childhood education: Inspired by direct observation of the children at play and documented using photos and direct quotations from the children. The Green Room focuses on the development of the whole child. Through exploration, inquiry, and play, the Green Room supports the children’s social, cognitive, and motor development as they find wonder in the world around them.', null, true, 4, '{"ages":"lower-preschool","blueprint":"classrooms","programs":"day","teachers":["06f57a4f-cabc-45fa-a356-d2d9d3c079d1","db36433f-8439-45d3-9081-38ee0d9bef74"]}'::jsonb, '2024-09-27T17:36:22.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', '129326ec-4081-45fd-a12d-bbce6e3d1cc4'), '129326ec-4081-45fd-a12d-bbce6e3d1cc4', 'mandarin-jade', 'Mandarin Jade (K - 3rd Grade)', E'Our school-age Mandarin programming expands upon the current CES philosophy. This program will follow a project-based model where children work collaboratively in the target language on large-scale projects that interest them, bringing in cultural and local community components and connections, as well as providing opportunities for DEI learning and activism. Mini lessons will target specific language learning, and support beginning literacy skills. Children will have regular opportunities for outdoor play, art, cooking, music, and movement.\n\nTwo, three, and five day enrollment options.', null, true, 5, '{"blueprint":"classrooms","teachers":["6099fb98-b07d-4e5c-907f-0a1e517d2d0f"]}'::jsonb, '2026-01-12T20:32:41.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', '1bdc622f-5bcd-4d93-ab82-89cac9bc1b49'), '1bdc622f-5bcd-4d93-ab82-89cac9bc1b49', 'mandarin-room', 'Mandarin Green & Purple', 'The Mandarin Rooms welcome children from 2.9 to 6 years old. Through immersion in the Mandarin language, and an emergent and play-based curriculum with a focus on the arts and outdoor exploration, we are able to accommodate students at all levels of Mandarin learning, and individually challenge them based on where they are in their language development. We expose children to the different traditions of the Mandarin-speaking cultures through the exploration of food, dance, holiday celebrations, and music.', null, true, 6, '{"ages":"preschool","blueprint":"classrooms","programs":"language","teachers":["d55c3300-37a9-45f6-9ad6-f6adee381cc2","b5bb8cd0-648d-4365-b5ed-6d82d8c1a81c","89f3addc-2951-465b-a6cb-4f3eec76d72b","c9517f69-24af-4d2c-b524-2133e2ed9aa7"]}'::jsonb, '2026-01-12T20:28:31.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', '73f44629-52d8-444e-8cc4-35a3a7569479'), '73f44629-52d8-444e-8cc4-35a3a7569479', 'orange-room', 'Orange Room', 'In the Orange room, young toddlers (who have turned 1.9 years old by September 1st) find a warm, inviting space to explore and connect. With their interests in mind we provide open-ended materials and process art projects in order to stretch children’s thinking and deepen children''s sense of wonder. We focus on building loving and supportive relationships with, and amongst, the children. Throughout the course of the year we embrace the many opportunities for children to practice sharing materials, space, and ideas for play, knowing these will be foundational pieces of their growing understanding of how to be part of a community.', null, true, 7, '{"ages":"toddler","blueprint":"classrooms","integer":1,"program_type":"day","programs":"day","teachers":["d120d817-6a1f-4fac-ab04-8804189991d3","c57e4fb9-2ffe-403f-9a2f-ea5b62d48ce3","56014be6-3e8c-4ff6-b500-039549190c03"]}'::jsonb, '2024-09-27T17:36:47.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', '7c58e147-8daa-4bf1-9ef4-0c2d74ac028f'), '7c58e147-8daa-4bf1-9ef4-0c2d74ac028f', 'purple-room', 'Purple Room', 'The Purple Room is an emergent curriculum classroom for Upper Preschool children. The projects and activities are based on the interests of the children and encompass areas of learning that include: science, art, math, literacy, sensory, dramatic play, and block play. Our classroom focuses on and supports every child’s social, emotional, cognitive, self-help, and physical development as they learn important skills needed for kindergarten and beyond. With over four decades of combined teaching experience, the Purple Room teachers provide unique learning opportunities and experiences for young children.', null, true, 8, '{"ages":"upper-preschool","blueprint":"classrooms","programs":"day","teachers":["9b517d7d-3b1c-432e-b9f9-700da7d5eb6b","da9b7489-43e6-42f9-837e-d46dfa84983a"]}'::jsonb, '2025-09-09T21:01:08.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', 'c63dac32-3295-4368-bb8a-f4f1e23b718f'), 'c63dac32-3295-4368-bb8a-f4f1e23b718f', 'rainbow-red', 'Rainbow Red', 'The Rainbow Rooms provide a relaxed learning environment for a group of four and seven young toddlers. The curriculum is driven by the interests of the children. Nurturing teachers foster the social, emotional, cognitive, and physical development of children through a play-based model, with a focus on the arts and outdoor exploration. The Rainbow Rooms also provide an immersion program for families seeking to have their child learn English as a second language.', 'toddler', false, 9, '{"ages":"toddler","blueprint":"classrooms","program_type":"day-program","programs":"language","teachers":["2f05d078-eb5b-429d-a912-291c0322b790"]}'::jsonb, '2024-08-05T12:34:53.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', 'a289ada5-75ed-4478-a0ac-457b827c8850'), 'a289ada5-75ed-4478-a0ac-457b827c8850', 'rainbow-room', 'Rainbow Room', E'The Rainbow Room provides a relaxed learning environment for young toddlers. The curriculum is driven by the interests of the children. Nurturing teachers foster the social, emotional, cognitive, and physical development of children through a play-based model, with a focus on the arts and outdoor exploration. \n\nThe Rainbow Room also provides an immersion program for families seeking to have their child learn English as a second language.', 'toddler', true, 10, '{"ages":"toddler","blueprint":"classrooms","program_type":"language-program","programs":"language","teachers":["70683307-d0b0-4e8e-b4bf-2bae5c3a0167","d120d817-6a1f-4fac-ab04-8804189991d3","ec4dc537-40cc-432f-b7fe-d4037bbce162"]}'::jsonb, '2025-09-09T21:01:50.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', '448d749d-93d0-4c81-bd6f-806e5e431849'), '448d749d-93d0-4c81-bd6f-806e5e431849', 'red-room', 'Red Room', 'In the Red Room, young toddlers (who have turned 1.9 years old by September 1st) have the opportunity to create their own knowledge through daily exploration, connections and interactions. We explore the environment through open-ended, play-based activities based on the children’s interests and play that is observed. Children form attachments to peers and teachers as they develop social, cognitive, motor and language skills.', null, true, 11, '{"ages":"toddler","blueprint":"classrooms","integer":1,"program_type":"day","programs":"day","teachers":["7eeffe6b-8ee3-4c8a-b7df-452c9f0f385e","26b39d59-4809-47b7-9f13-650c6fc30bd5","d55c3300-37a9-45f6-9ad6-f6adee381cc2"]}'::jsonb, '2024-09-27T17:37:34.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', '9f3c379b-1411-420e-a43b-8370437954d0'), '9f3c379b-1411-420e-a43b-8370437954d0', 'spanish-room', 'Spanish Amber & Blue', 'The Spanish Rooms welcome children ranging from 2.9 to 6 years old. Through immersion in the Spanish language, and an emergent and play-based curriculum with a focus on the arts and outdoor exploration, we are able to accommodate students at all levels of Spanish learning, and individually challenge them based on where they are in their language development. We expose children to the different traditions of Spanish and Latin American cultures through the exploration of food, dance, celebrations, and music.', null, true, 12, '{"ages":"preschool","blueprint":"classrooms","programs":"language","teachers":["328dac6a-39bb-4cfe-bfca-9d8b36a34b5c","e1eef63c-70fd-46bf-8a52-d565876832dc","e0a9289c-a6ee-4e10-9270-aa2d3fef591c","e1cb2b8e-7150-465b-b287-0f00c9ae794b"]}'::jsonb, '2026-01-12T20:28:56.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('classrooms', '8f6909ad-b9a1-41e8-b54e-b0f90bfc48ba'), '8f6909ad-b9a1-41e8-b54e-b0f90bfc48ba', 'yellow-room', 'Yellow Room', 'The Yellow Room is for Lower Preschool children. In this room, we create a close classroom community, welcoming children from the toddler classes and children new to the school. The Yellow Room has a strong focus on communication, social-emotional development, and a strong sense of self and others. Small-world play and storytelling support this learning and the integration of literacy, math, and other academic learning objectives.', null, true, 13, '{"ages":"lower-preschool","blueprint":"classrooms","integer":2,"programs":"day","teachers":["8cd47516-62bd-4fac-98bb-5ee4df634967","28d307a1-5066-4d82-bbe0-7e5787034d0b"]}'::jsonb, '2025-09-09T21:02:17.000Z', 'bekah@cambridge-ellis.org')
