insert into public.events
  (id, legacy_ref, slug, title, event_date, start_time, end_time, location, zoom_link, image_asset_id, short_description, details, calendar_link, published, legacy, source_updated_at, source_updated_by)
values
  (public.ces_uuid('events', '5866f185-59b9-4338-b0f4-ab738e61fc1f'), '5866f185-59b9-4338-b0f4-ab738e61fc1f', 'annual-auction-and-community-celebration', 'Annual Auction and Community Celebration', '2024-04-27'::date, '06:30'::time, '11:00'::time, 'Harry Parker Boathouse, 20 Nonatum Rd, Brighton, MA', null, public.ces_uuid('assets', 'ces-house.jpg'), 'Join CES'' biggest celebration of the year! Dinner, drinks, dancing, and fun are included in the price of your ticket. In keeping with our Artisan Program, the theme of this year''s event will be Yoga movement and flow.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://e.givesmart.com/events/xXk/","rel":null,"target":null,"title":null}}],"text":"Auction and Community Celebration tickets are now available for purchase!"}]}]}'::jsonb, 'https://calendar.google.com/calendar/event?action=TEMPLATE&tmeid=NWpzNXI1OXFxZWw3dmIxc2xxMDYzOTg3YTIgY19mNDRmNTg2NWYwNTVlNmM5MTVmNGQxY2RkZjliNzRjMzFjOGQ0YWUxZjNlZjkyZWY2ZDU4ZDllNTc2NTQ5OTc0QGc&tmsrc=c_f44f5865f055e6c915f4d1cddf9b74c31c8d4ae1f3ef92ef6d58d9e576549974%40group.calendar.google.com', false, '{"blueprint":"events"}'::jsonb, '2024-03-15T14:56:37.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', 'c4feb5e5-5430-4c3d-849f-dae09b90a7f9'), 'c4feb5e5-5430-4c3d-849f-dae09b90a7f9', 'boston-area-school-fair-presented-by-cambridge-ellis-school', 'Boston Area School Fair', '2026-09-26'::date, '10:00'::time, '12:00'::time, '80 Trowbridge St, Cambridge', null, public.ces_uuid('assets', 'school-fair-website-graphic.jpg'), 'Where else will you have the opportunity to chat with admissions representatives from over 25 Boston area preK through 12th grade independent and public schools all in one place? On Saturday, September 26th from 10am to 12pm, Cambridge-Ellis is the place you’ll want to be! Come see what makes each school unique, have all your questions answered, and head home with loads of information and some pretty awesome swag to boot!', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Schools represented at the Boston Area School Fair will include:"}]},{"type":"paragraph","content":[{"type":"text","text":"Acera School"}]},{"type":"paragraph","content":[{"type":"text","text":"The Advent School"}]},{"type":"paragraph","content":[{"type":"text","text":"Allium Montessori School"}]},{"type":"paragraph","content":[{"type":"text","text":"Atrium School"}]},{"type":"paragraph","content":[{"type":"text","text":"BB&N School"}]},{"type":"paragraph","content":[{"type":"text","text":"Belmont Day School"}]},{"type":"paragraph","content":[{"type":"text","text":"Birches School"}]},{"type":"paragraph","content":[{"type":"text","text":"Brimmer and May"}]},{"type":"paragraph","content":[{"type":"text","text":"British International School of Boston"}]},{"type":"paragraph","content":[{"type":"text","text":"Cambridge-Ellis School"}]},{"type":"paragraph","content":[{"type":"text","text":"Cambridge Montessori School"}]},{"type":"paragraph","content":[{"type":"text","text":"The Chestnut Hill School"}]},{"type":"paragraph","content":[{"type":"text","text":"Dexter Southfield"}]},{"type":"paragraph","content":[{"type":"text","text":"EFB - Ecole Fran\u00e7aise de Boston"}]},{"type":"paragraph","content":[{"type":"text","text":"Fayerweather Street School"}]},{"type":"paragraph","content":[{"type":"text","text":"German International School Boston"}]},{"type":"paragraph","content":[{"type":"text","text":"International School of Boston"}]},{"type":"paragraph","content":[{"type":"text","text":"Jackson Walnut Park School"}]},{"type":"paragraph","content":[{"type":"text","text":"Kingsley Montessori School"}]},{"type":"paragraph","content":[{"type":"text","text":"The Learning Project Elementary School"}]},{"type":"paragraph","content":[{"type":"text","text":"Lesley Ellis School"}]},{"type":"paragraph","content":[{"type":"text","text":"The Meadowbrook School of Weston"}]},{"type":"paragraph","content":[{"type":"text","text":"Milton Academy"}]},{"type":"paragraph","content":[{"type":"text","text":"The Park School"}]},{"type":"paragraph","content":[{"type":"text","text":"Prospect Hill Academy"}]},{"type":"paragraph","content":[{"type":"text","text":"Shady Hill School"}]},{"type":"paragraph","content":[{"type":"text","text":"Tenacre Country Day School"}]},{"type":"paragraph","content":[{"type":"text","text":"Thacher Montessori School"}]},{"type":"paragraph","content":[{"type":"text","text":"Torit Montessori School"}]},{"type":"paragraph","content":[{"type":"text","text":"Wellan Montessori School"}]},{"type":"paragraph","content":[{"type":"text","text":"Bring your prospective students, or come solo. It will be a fun and informative event for all ages! Our playground will be open during the hours of the event (please make sure an adult is supervising your child at all times)."}]},{"type":"paragraph","content":[{"type":"text","text":"Our parking lot will be reserved for our vendors and their tents. Parking considerations have been granted through the city of Cambridge on the day of the event between 10am-1pm on Trowbridge St., Kirkland St., Roberts Rd., and Irving St. There is also metered parking located on Cambridge St."}]}]}'::jsonb, null, true, '{"blueprint":"events"}'::jsonb, '2026-08-25T12:39:23.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '93191b3e-c120-4de8-8e66-23ee3bb8df23'), '93191b3e-c120-4de8-8e66-23ee3bb8df23', 'community-welcome-night', 'Community Welcome Night', '2023-08-31'::date, '17:00'::time, '20:00'::time, '80 Trowbridge St, Cambridge', null, null, 'Let''s kick off the 2023-24 school year with our annual welcome event (previously known as Parent Orientation)! Meet our faculty, families, and enjoy beverages and snacks on the CES playground. Reminder: This is an in person, adult only event.', null, null, false, '{"blueprint":"events"}'::jsonb, '2023-08-08T00:54:16.000Z', 'conrad.fulbrook@gmail.com'),
  (public.ces_uuid('events', '04b9e12d-12b7-4af3-bca5-9fa38b992a66'), '04b9e12d-12b7-4af3-bca5-9fa38b992a66', 'day-program-last-day', 'Day Program Last Day', '2025-06-13'::date, '08:30'::time, '12:00'::time, '80 Trowbridge St. Cambridge, MA', null, null, 'Day Program Teachers will reach out to classroom members with details about their last day celebration! Dismissal is at 12pm. We hope to see you there!', null, null, false, '{"blueprint":"events"}'::jsonb, '2025-07-15T13:54:41.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '43e15d45-86d8-4d2a-9b9c-627f7e4e953f'), '43e15d45-86d8-4d2a-9b9c-627f7e4e953f', 'fall-growth-conferences', 'Fall Growth Conferences', '2024-10-25'::date, null, null, '80 Trowbridge St, Cambridge', null, null, 'The school will be closed to students on Friday, October 25th, as we host Fall Growth Conferences. Join your child''s classroom teachers for a discussion of development and goals as they begin the school year.', null, 'https://calendar.google.com/calendar/event?action=TEMPLATE&tmeid=MDQ4NmpjOTdhazhhcnFxZHFlcmkwaGtybDYgY19mNDRmNTg2NWYwNTVlNmM5MTVmNGQxY2RkZjliNzRjMzFjOGQ0YWUxZjNlZjkyZWY2ZDU4ZDllNTc2NTQ5OTc0QGc&tmsrc=c_f44f5865f055e6c915f4d1cddf9b74c31c8d4ae1f3ef92ef6d58d9e576549974%40group.calendar.google.com', false, '{"blueprint":"events","duplicated_from":"549d8e76-c049-4758-af34-88240ebcb682"}'::jsonb, '2024-09-25T19:15:01.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '8d4d1967-95b8-4fd9-a1f2-35ba4aed1e26'), '8d4d1967-95b8-4fd9-a1f2-35ba4aed1e26', 'february-break', 'February Break', '2024-02-19'::date, null, null, '80 Trowbridge St, Cambridge', null, null, 'CES will be closed the week of February 19-23rd for February Break. We will return to school on Monday, February 26th.', null, 'https://calendar.google.com/calendar/event?action=TEMPLATE&tmeid=MjdvdHNrY2xobGVlZWY1dmRpdXRkcjBnNmwgY19mNDRmNTg2NWYwNTVlNmM5MTVmNGQxY2RkZjliNzRjMzFjOGQ0YWUxZjNlZjkyZWY2ZDU4ZDllNTc2NTQ5OTc0QGc&tmsrc=c_f44f5865f055e6c915f4d1cddf9b74c31c8d4ae1f3ef92ef6d58d9e576549974%40group.calendar.google.com', false, '{"blueprint":"events"}'::jsonb, '2024-02-13T18:11:05.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '7b2cfe8c-6aca-4b47-9fe7-f6e6372471a3'), '7b2cfe8c-6aca-4b47-9fe7-f6e6372471a3', 'festival-of-lights', 'Festival of Lights', '2025-12-06'::date, '16:00'::time, '18:00'::time, 'Big Playground', null, null, 'The Festival of Lights is a popular CES family event with plenty of activities, delicious food and hot drinks, and a special arts performer to bring everyone together! It is hosted by the Community Builders and shaped by volunteer participation; CES community members volunteer to share a family tradition around lights. If you would like to share a tradition, lead an activity, or help with set up, please contact pta@cambridge-ellis.org.', null, null, false, '{"blueprint":"events"}'::jsonb, '2026-01-14T15:57:40.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '554ffd25-93ec-4b5d-a049-bfdba809b95a'), '554ffd25-93ec-4b5d-a049-bfdba809b95a', 'language-program-last-day', 'Language Program Last Day', '2025-06-12'::date, '03:00'::time, '06:00'::time, '80 Trowbridge St. Cambridge, MA', null, null, 'Language Program Teachers will reach out to classroom members with details about their last day celebration! We hope to see you there!', null, null, false, '{"blueprint":"events"}'::jsonb, '2025-07-15T13:54:31.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '31a80cc0-b6a1-4840-ba78-b18525b82485'), '31a80cc0-b6a1-4840-ba78-b18525b82485', 'last-day-of-the-summer-program', 'Last Day of the Summer Program', '2025-07-18'::date, null, null, 'CES', null, null, 'Goodbye until the 2025-26 school year!', null, null, false, '{"blueprint":"events"}'::jsonb, '2025-06-04T00:11:57.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', 'da8ac21d-cd3b-4fb2-8351-0b7dbb0b9509'), 'da8ac21d-cd3b-4fb2-8351-0b7dbb0b9509', 'let-s-play', 'Let''s Play!', '2026-01-14'::date, null, null, 'Cambridge-Ellis School', null, null, 'Let''s Play', null, null, false, '{"blueprint":"events"}'::jsonb, '2026-01-14T16:00:20.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', 'ecbb3d41-19c6-47b5-a3de-417466f44ef7'), 'ecbb3d41-19c6-47b5-a3de-417466f44ef7', 'open-house', 'Open House', '2026-11-07'::date, '10:00'::time, '12:00'::time, '80 Trowbridge St, Cambridge', null, null, 'Come see what makes Cambridge-Ellis School such a joyous place for children and their families! Join us on November 7th anytime between 10am and 12pm for a self-guided tour of our beautiful indoor and outdoor spaces.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"As you walk through our campus, you will be greeted by a variety of Cambridge-Ellis community members including teachers, current families, Board members, and Leadership members. We will be here to chat with you and answer any questions you may have about our amazing programs, so we hope to see you all there!"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Bring your prospective student, or come solo. It will be a fun and informative event for all ages!"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Our parking lot will be reserved for community volunteers. Parking considerations have been granted through the city of Cambridge on the day of the event between 10am-1pm on Trowbridge St., Kirkland St., and Irving St. There is also metered parking located on Cambridge St."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Reach out to "},{"type":"text","marks":[{"type":"link","attrs":{"href":"mailto:christina@cambridge-ellis.org","rel":null,"target":null,"title":null}}],"text":"Christina"},{"type":"text","text":" if you have any questions about this special event."}]}]}'::jsonb, null, true, '{"blueprint":"events"}'::jsonb, '2026-07-02T15:48:42.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '973c5464-c35a-4388-bde0-2989adba47e7'), '973c5464-c35a-4388-bde0-2989adba47e7', 'outdoor-movie-night', 'Outdoor Movie Night', '2024-11-02'::date, '17:00'::time, null, 'Big Playground', null, null, E'The Community Building Committee is hosting an Outdoor Movie Night on the CES playground on Sat 11/2 from 5-7pm. More details to come. \n\n﻿For questions, to volunteer to help, or to suggest a short for us to show, email the Community Building Committee at pta@cambridge-ellis.org.', null, null, false, '{"blueprint":"events"}'::jsonb, '2024-09-25T19:17:59.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '4cf66e60-371a-40f2-908c-ca55230b2633'), '4cf66e60-371a-40f2-908c-ca55230b2633', 'pictureday', 'Picture Day!', '2024-10-29'::date, null, null, '80 Trowbridge St, Cambridge', null, null, 'Picture Day for all enrolled students. The rain date will be October 30, 2024.', null, null, false, '{"blueprint":"events"}'::jsonb, '2024-09-25T19:11:08.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '12f05ade-fd49-46d5-a978-349b0eb04553'), '12f05ade-fd49-46d5-a978-349b0eb04553', 'playground-ribbon-cutting-social', 'Playground Ribbon Cutting Social', '2024-10-17'::date, '19:00'::time, '20:30'::time, 'Small Playground', null, null, 'This adult-only event will be held on Thursday, October 17 from 7-8:30 pm on our newly renovated Small Playground! Our CES playgrounds spread a magic that is felt by all within the community, and we hope to share that magic back with you at our ribbon-cutting event! As the new Assistant Director and Language Program Director, we want to express our gratitude, socialize, and celebrate over drinks and light refreshments. We hope to see you there!', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Please "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://docs.google.com/forms/d/1N5cwwddhRbKrOoKw8saEcGxAJVCKv6j8itWiPHqhXSA/edit","rel":null,"target":null,"title":null}}],"text":"RSVP"}]}]}'::jsonb, null, false, '{"blueprint":"events"}'::jsonb, '2024-10-04T19:14:24.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '549d8e76-c049-4758-af34-88240ebcb682'), '549d8e76-c049-4758-af34-88240ebcb682', 'spring-growth-conferences', 'Spring Growth Conferences', '2025-03-14'::date, null, null, '80 Trowbridge St, Cambridge', null, null, 'The school will be closed to students on Friday, March 14th as we host Spring Growth Conferences. Join your child''s classroom teachers for a discussion of growth and development since the fall conference and to set goals for the remainder of the school year.', null, null, false, '{"blueprint":"events"}'::jsonb, '2025-02-28T17:55:44.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', '5b679a60-577f-4b84-97bb-4d97e2363433'), '5b679a60-577f-4b84-97bb-4d97e2363433', 'start-of-summer-program', 'Start of Summer Program', '2025-06-23'::date, null, null, 'CES', null, null, 'Our Summer Program kicks off on June 23rd! Please ensure the school has your child''s necessary paperwork before the start of the program.', null, null, false, '{"blueprint":"events"}'::jsonb, '2025-07-15T13:55:17.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', 'd3cd3fa4-0f4e-4e31-9cca-abd017ba4b5c'), 'd3cd3fa4-0f4e-4e31-9cca-abd017ba4b5c', 'story-slam', 'Story Slam', '2024-03-07'::date, '07:00'::time, '08:30'::time, E'Upstairs Space at CES\n80 Trowbridge St, Cambridge', 'Zoom link to come', public.ces_uuid('assets', 'story-slam-reschedule.jpg'), 'Join us for a night of stories and community. Think The Moth from NPR. Community members can choose to join us in person or to watch the Zoom broadcast.', null, 'https://calendar.google.com/calendar/event?action=TEMPLATE&tmeid=MGVjajlmbG5rOTd2anU3bDJxampmZmRpZXUgY19mNDRmNTg2NWYwNTVlNmM5MTVmNGQxY2RkZjliNzRjMzFjOGQ0YWUxZjNlZjkyZWY2ZDU4ZDllNTc2NTQ5OTc0QGc&tmsrc=c_f44f5865f055e6c915f4d1cddf9b74c31c8d4ae1f3ef92ef6d58d9e576549974%40group.calendar.google.com', false, '{"blueprint":"events"}'::jsonb, '2024-02-13T18:14:38.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('events', 'faec0f17-fff6-4b71-9d50-dd7f0ddda612'), 'faec0f17-fff6-4b71-9d50-dd7f0ddda612', 'teacher-appreciation-week', 'Teacher Appreciation Week', '2025-03-10'::date, null, null, 'Cambridge-Ellis School', null, null, 'Shower your classroom teachers with a little extra love this week. Please contact the Community Builders if you''d like to support with school-wide efforts.', null, null, false, '{"blueprint":"events"}'::jsonb, '2025-02-28T17:57:25.000Z', 'bekah@cambridge-ellis.org')
insert into public.promoted
  (id, legacy_ref, slug, title, subtitle, address, summary, event_date, start_time, end_time, image_asset_id, published, sort_order, legacy, source_updated_at, source_updated_by)
values
  (public.ces_uuid('promoted', '1657573a-478a-450e-b55f-83ecbd04812e'), '1657573a-478a-450e-b55f-83ecbd04812e', 'admissions-season', 'Admissions season for the 2026-27 school year is now open!', null, null, null, null, null, null, public.ces_uuid('assets', '15219634_1141044685963611_3316175230264602101_n.jpg'), false, 1, '{"blueprint":"promoted"}'::jsonb, '2026-02-02T14:16:19.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', 'aa8e7d5f-11d6-4857-bd62-6f4ecbe6be5b'), 'aa8e7d5f-11d6-4857-bd62-6f4ecbe6be5b', 'annual-auction-and-community-celebration', 'Annual Auction and Community Celebration', 'Join CES'' biggest party of the year!', E'Harry Parker Boathouse\n20 Nonatum Rd,\nBrighton, MA', 'Visit our Auction webpage under the Giving tab to purchase tickets for the event. Dinner, drinks, and dancing are included with your ticket price. All proceeds from the event go towards supporting our playground renovations!', '2024-04-27'::date, '06:30'::time, '11:00'::time, public.ces_uuid('assets', 'ces-house.jpg'), false, 2, '{"blueprint":"promoted"}'::jsonb, '2024-03-15T14:48:16.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', 'c6491f8c-6588-4930-82ad-aaeeef02fbb8'), 'c6491f8c-6588-4930-82ad-aaeeef02fbb8', 'boston-area-school-fair', 'Boston Area School Fair', 'Click on ''Events'' to learn more about it.', 'Cambridge-Ellis School / 80 Trowbridge St. / Cambridge, MA 02138', null, '2024-09-28'::date, '10:00'::time, '12:00'::time, public.ces_uuid('assets', 'school-fair-website-banner-1725645772.jpg'), false, 3, '{"blueprint":"promoted"}'::jsonb, '2024-09-06T18:07:54.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', '6fa2d96e-c0b1-4308-8e81-58969f163116'), '6fa2d96e-c0b1-4308-8e81-58969f163116', 'february-break', 'February Break', 'CES will be closed the week of February 19-23rd for February Break. We will return to school on Monday, February 26th.', null, null, null, null, null, public.ces_uuid('assets', 'ces-house.jpg'), false, 4, '{"blueprint":"promoted"}'::jsonb, '2024-02-13T18:09:06.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', '29985e75-e0a5-45ec-8b15-f72a53123583'), '29985e75-e0a5-45ec-8b15-f72a53123583', 'last-days-of-school', 'Last Days of School!', 'All families are invited to join us at CES for Last Day Celebrations! Classroom teachers will reach out with classroom specific details. We can''t wait to celebrate our growth and learning with you!', null, 'The last day of the Language Program is Thursday, 6/6. The last day of the Day Program is Friday, 6/7. Don''t forget that Friday, 6/7 is a half day with dismissal at 12pm.', '2024-06-07'::date, null, null, public.ces_uuid('assets', 'ces-house.jpg'), false, 5, '{"blueprint":"promoted"}'::jsonb, '2024-05-30T16:36:39.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', '8b87e474-816a-435f-ab1e-5d5e42f22e45'), '8b87e474-816a-435f-ab1e-5d5e42f22e45', 'new-k-3rd-grade-mandarin-afterschool-program-apply-for-the-2025-26-school-year-today', 'We anticipate spots opening in our Language Immersion Program! Apply for the 2026-27 school year today!', null, null, null, null, null, null, public.ces_uuid('assets', '15219634_1141044685963611_3316175230264602101_n.jpg'), false, 6, '{"blueprint":"promoted","link":"https://cambridge-ellis.myschoolapp.com/app#login/apply"}'::jsonb, '2026-07-02T17:52:30.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', 'f4565d23-a220-4388-8f67-054986dfe81f'), 'f4565d23-a220-4388-8f67-054986dfe81f', 'open-house', 'Join us for our Open House!', null, null, null, '2024-11-02'::date, '10:00'::time, '12:00'::time, public.ces_uuid('assets', 'open-house-website-banner-1728579309.jpg'), false, 7, '{"blueprint":"promoted"}'::jsonb, '2024-10-11T14:44:10.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', '66792467-5f8c-4313-9329-e5397414e409'), '66792467-5f8c-4313-9329-e5397414e409', 'spring-growth-conferences', 'Spring Growth Conferences', 'Join your child''s classroom teachers for a discussion of their development and growth towards goals set in the fall.', 'The school will be closed to students on conference day. Families can sign up for conference times and childcare using links found in the CES Weekly.', null, '2024-03-15'::date, null, null, public.ces_uuid('assets', 'ces-house.jpg'), false, 8, '{"blueprint":"promoted"}'::jsonb, '2024-02-29T23:49:25.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', '4cffd1c6-7fd3-4538-94d4-e13758ed790d'), '4cffd1c6-7fd3-4538-94d4-e13758ed790d', 'start-of-2024', 'Start of 2024-25 School Year!', null, null, 'Our school year begins on September 3rd with two transition days. Classroom assignments will be shared by school leadership on August 5th. Caregivers will receive a welcome email from their classroom teachers with more information about the start of the school year in mid-August.', '2024-09-03'::date, null, null, public.ces_uuid('assets', 'ces-house.jpg'), false, 9, '{"blueprint":"promoted"}'::jsonb, '2024-10-11T14:39:29.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', 'b72fd205-d2ad-41d5-95cf-a0ab17144a2f'), 'b72fd205-d2ad-41d5-95cf-a0ab17144a2f', 'story-slam', 'Story Slam', 'Join us for a night of storytelling and community!', '80 Trowbridge St, Cambridge', 'Join us upstairs at CES to hear interesting, emotional, and funny stories from members of our community. Think The Moth from NPR. Drinks and snacks will be provided. We will be broadcasting this event over Zoom for those who are unable to attend in person.', '2024-03-07'::date, '07:00'::time, '08:30'::time, public.ces_uuid('assets', 'ces-house.jpg'), false, 10, '{"blueprint":"promoted"}'::jsonb, '2024-02-13T18:07:38.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', 'bf3c65f4-5842-4478-a27d-e133afe96931'), 'bf3c65f4-5842-4478-a27d-e133afe96931', 'summer-camp-sessions-a-and-b', 'Community Welcome Night', 'Let''s kick off the 2023-24 school year with our annual welcome event (previously known as Parent Orientation)!', '80 Trowbridge St, Cambridge', 'Meet our faculty, families, and enjoy beverages and snacks on the CES playground. Reminder: This is an in person, adult only event.', '2023-08-31'::date, '07:00'::time, '08:00'::time, public.ces_uuid('assets', 'ces-house.jpg'), false, 11, '{"blueprint":"promoted"}'::jsonb, '2023-08-01T15:34:09.000Z', 'bekah@cambridge-ellis.org'),
  (public.ces_uuid('promoted', 'edb127b0-caf5-40be-9056-5fbfb4109b72'), 'edb127b0-caf5-40be-9056-5fbfb4109b72', 'summer-program-2026-registration-is-now-open-for-all-famil', 'Summer Program 2026 Registration is now open for all Families!', 'June and July are full of fun, exploration, and water play at our CES summer program!', null, 'Visit the Summer Program Registration page under Programs to register! Limited spaces available!', null, null, null, public.ces_uuid('assets', 'ces-house.jpg'), false, 12, '{"blueprint":"promoted"}'::jsonb, '2026-02-23T02:01:03.000Z', 'bekah@cambridge-ellis.org')
