  (public.ces_uuid('announcements', '377340dc-5ec0-473a-9ed0-c1b272d64aba'), '377340dc-5ec0-473a-9ed0-c1b272d64aba', '2023-24-admissions-season-now-open-apply-today', 'Summer Camp 2023 Registration Opens to the Public, 2/15!', null, false, true, '{"blueprint":"announcements","link":"53cf3d97-1b19-4551-a080-30b69ec56ef6"}'::jsonb, '2023-02-15T04:57:29.000Z', 'bekah@cambridge-ellis.org'),
