insert into public.inspiring_quotes
  (id, legacy_ref, slug, quote, attribution, published, legacy, source_updated_at, source_updated_by)
values
  (public.ces_uuid('inspiring_quotes', '9db25766-8dcb-4163-ace6-e89a21f814cd'), '9db25766-8dcb-4163-ace6-e89a21f814cd', 'children-are-likely-to-live-up-to-what-you-believe-of-them', 'Children are likely to live up to what you believe of them.', 'Lady Bird Johnson', true, '{"blueprint":"inspiring_quotes"}'::jsonb, '2021-10-28T17:10:33.000Z', 'conrad.fulbrook@gmail.com'),
  (public.ces_uuid('inspiring_quotes', 'e695a68a-9a62-4c66-9e80-e9b041d1ecb5'), 'e695a68a-9a62-4c66-9e80-e9b041d1ecb5', 'children-are-not-things-to-be-molded-but-are-people-to-be-unfolded', 'Children are not things to be molded, but are people to be unfolded.', 'Jess Lair', true, '{"blueprint":"inspiring_quotes"}'::jsonb, '2021-10-28T17:12:25.000Z', 'conrad.fulbrook@gmail.com'),
  (public.ces_uuid('inspiring_quotes', '66015434-ef0d-4767-892b-2bb4b753c99d'), '66015434-ef0d-4767-892b-2bb4b753c99d', 'children-must-be-taught-how-to-think-not-what-to-think', 'Children must be taught how to think, not what to think.', 'Margaret Mead', true, '{"blueprint":"inspiring_quotes"}'::jsonb, '2021-10-28T17:10:59.000Z', 'conrad.fulbrook@gmail.com'),
  (public.ces_uuid('inspiring_quotes', '66fa58e6-abd5-4051-8e91-d0a3f2dcfa62'), '66fa58e6-abd5-4051-8e91-d0a3f2dcfa62', 'our-heritage-and-ideals-our-code-and-standards-the-things-we-live-by-and-teach-our-children-are-preserved-or-diminished-by-how-freely-we-exchange-ideas-and-feelings', 'Our heritage and ideals, our code and standards – the things we live by and teach our children – are preserved or diminished by how freely we exchange ideas and feelings.', 'Walt Disney', true, '{"blueprint":"inspiring_quotes"}'::jsonb, '2021-10-28T17:15:51.000Z', 'conrad.fulbrook@gmail.com'),
  (public.ces_uuid('inspiring_quotes', '4fc47c84-1807-442a-8e9e-46a5b58433af'), '4fc47c84-1807-442a-8e9e-46a5b58433af', 'while-we-try-to-teach-our-children-all-about-life-our-children-teach-us-what-life-is-all-about', 'While we try to teach our children all about life, Our children teach us what life is all about.', 'Angela Schwindt', true, '{"blueprint":"inspiring_quotes"}'::jsonb, '2021-10-28T17:11:20.000Z', 'conrad.fulbrook@gmail.com')
